window.DOSIK=window.DOSIK||{};DOSIK["ip_3"]={"1":[{"t":"def","term":"직무발명","text":"종업원등이 그 직무에 관하여 한 발명으로, 성질상 사용자등의 업무범위에 속하고 발명 행위가 종업원의 현재 또는 과거 직무에 속하는 것을 말한다"},{"t":"flow","title":"직무발명 제도의 도입","steps":["직무발명 제도는 1974년 특허법에서 도입되었다","2006년 발명진흥법으로 근거법이 바뀌어 현재에 이르고 있다","사용자와 종업원의 이익을 합리적으로 조정해 R&D 투자를 촉진하고 종업원의 혁신적인 발명활동을 장려하려는 취지"]},{"t":"vs","title":"직무발명 보상금의 과세","cols":[{"name":"재직 중","items":["발명진흥법에 따른 직무발명으로 사용자등으로부터 받는 보상금은 소득세법상 근로소득과 퇴직소득 중 비과세소득으로 규정되어 있다"]},{"name":"퇴직 후","items":["종업원등이 퇴직한 후 지급받는 직무발명보상금은 소득세법상 기타소득으로 대통령령이 정하는 금액까지 인정된다"]}]}],"2":[{"t":"table","title":"통상실시권","head":["구분","내용"],"rows":[["통상실시권 취득","종업원등이 직무발명으로 특허를 받으면 사용자등은 그 특허권에 대해 통상실시권을 가진다"],["중소기업이 아닌 사용자등","종업원등과 협의를 거쳐 승계·전용실시권 설정에 관한 계약이나 근무규정을 미리 두지 않으면 통상실시권을 가지지 못한다"],["제3자가 특허를 받은 경우","사용자가 아닌 종업원이나 종업원에게서 권리를 승계한 제3자가 특허를 받은 경우에도 사용자는 대가 없이 통상실시권을 취득한다"]]},{"t":"def","term":"예약승계","text":"종업원의 직무발명에 대해 미리 사용자가 권리를 승계하거나 전용실시권을 설정하기로 하는 계약이나 근무규정을 말한다","ex":["직무발명 외의 종업원 발명에 대해 미리 사용자등에게 권리를 승계시키거나 전용실시권을 설정하도록 하는 계약이나 근무규정의 조항은 무효이다"]}],"3":[{"t":"tree","title":"국유특허 보상","root":"공무원의 직무발명에 대한 권리는 국가나 지방자치단체가 승계할 수 있으며, 승계한 특허권등은 국유나 공유로 한다","branches":[["처분과 관리","국유로 된 특허권등의 처분과 관리는 특허청장이 관장하며 그 처분과 관리에 필요한 사항은 대통령령으로 정한다"],["등록보상금","국가공무원의 국유특허권 등록보상금은 특허청장이 고시하는 바에 따라 지급하며 권리마다 50만 원의 범위에서 정한다 · 국유 실용신안권은 권리마다 30만 원, 국유 디자인권은 권리마다 20만 원의 범위에서 지급한다"],["처분보상금","국가가 직무발명의 권리를 유상으로 처분한 경우 처분수입금의 100분의 50 범위에서 발명자에게 지급한다"]]},{"t":"table","title":"기관포상금","head":["처분수입금","기관포상금"],"rows":[["1억 원을 넘으면","1천만 원"],["5천만 원 초과 1억 원 이하","500만 원"],["1만 원 초과 5천만 원 이하","100만 원"]]},{"t":"def","term":"산학협력단","text":"대학은 학교규칙으로 정하는 바에 따라 산학연협력 업무를 관장하는 산학협력단을 둘 수 있으며 산학협력단은 법인으로 한다","ex":["산학협력단은 재원 수입에 기여한 교직원 및 학생에 대한 보상금을 지출할 수 있다"]}],"4":[{"t":"def","term":"직무발명 보상제도","text":"종업원이 개발한 직무발명을 기업이 승계·소유하도록 하고 종업원에게는 정당한 보상을 해 주는 제도이다"},{"t":"table","title":"보상규정","head":["구분","내용"],"rows":[["작성","사용자등은 보상형태, 보상액 결정 기준, 지급방법 등이 명시된 보상규정을 작성하고 종업원등에게 서면으로 알려야 한다"],["불리한 변경","보상규정을 종업원등에게 불리하게 변경할 때에는 그 규정의 적용을 받는 종업원등 과반수의 동의를 받아야 한다"],["정당한 보상","사용자등이 규정에 따라 보상한 경우 정당한 보상으로 보지만, 사용자가 얻은 이익과 종업원의 공헌 정도를 고려하지 않았다면 그렇지 않다"],["출원하지 않는 경우","사용자가 직무발명 권리를 승계한 후 특허출원을 하지 않는 경우에도 종업원에게 정당한 보상을 하여야 한다"],["도입률","우리나라 기업의 직무발명 보상제도 도입률은 2017년 기준 65%로 87%인 일본보다 낮고, 중소기업은 대기업·중견기업보다 낮은 편이다"]]}],"5":[{"t":"flow","title":"직무발명 승계 및 보상 절차","steps":["발명신고","승계결정","직무발명 활용","발명자 보상"]},{"t":"table","title":"종업원과 사용자등","head":["구분","내용"],"rows":[["종업원의 통지","종업원은 직무발명을 완성한 후 지체 없이 사용자등에게 서면으로 알려야 하며, 2명 이상이 공동으로 완성했다면 공동으로 알려야 한다"],["예약승계규정이 없는 사용자등","종업원의 완성 통지를 받은 날부터 4개월 이내에 권리 승계 여부를 서면으로 알려야 한다 · 종업원의 의사와 다르게 직무발명 권리의 승계를 주장할 수 없다"],["종업원의 권리","종업원은 1차적으로 특허를 받을 권리를 가지며, 발명자로 특허출원서에 게재될 권리와 사용자에게 승계해 준 경우 정당한 보상을 받을 권리를 가진다"],["종업원의 의무","직무발명 완성사실을 지체 없이 문서로 통지할 의무와 사용자가 출원할 때까지 발명에 관한 비밀을 유지할 의무가 있다"]]}],"6":[{"t":"tree","title":"직무발명 보상의 종류","root":"직무발명 보상은 금전적 보상과 비금전적 보상으로 나뉘며 제안·출원·등록·실시 등 발명 단계에 따라 종류를 구분할 수 있다","branches":[["발명(제안)보상","특허청에 출원하기 전에 받는 보상으로, 출원 여부와 상관없이 종업원의 아이디어와 노력에 대한 장려금 성격을 가진다"],["출원유보보상","사용자가 직무발명을 노하우로 보존하거나 공개 시 손해가 우려되어 출원을 유보할 때 지급하는 보상이다"],["출원보상","미확정 권리에 대한 대가이므로 장려금 성격을 가지며, 출원 후 후원배제 효과와 선원의 지위를 얻는다는 점에서 지급한다"],["등록보상","사용자가 승계한 발명이 등록 결정되어 특허등록되었을 때 지급하는 보상이다"],["실시(실적)보상","사용자가 출원 중이거나 등록된 발명을 실시해 이익을 얻었을 때 이익의 액에 따라 차등 지급하는 보상이다"],["처분보상","사용자가 직무발명의 권리나 특허권을 타인에게 양도하거나 실시를 허여했을 때 처분금액의 일정 비율로 지급하는 보상이다"]]},{"t":"table","title":"실시보상·기타보상","head":["구분","내용"],"rows":[["자사실시보상·타사실시보상","자사실시보상은 발명자가 속한 회사에서 직무발명을 이용해 수익이 생길 때, 타사실시보상은 라이선스로 이전해 기술료 수입이 생길 때 지급한다"],["기타보상","출원발명의 심사청구 시 지급하는 심사청구보상과 타인의 출원발명을 무효로 하거나 침해를 적발한 경우의 방어보상 등이 있다"],["비금전적 보상","직무발명 보상은 금전적 보상이 일반적이지만 유급휴가, 승진, 해외연수 같은 비금전적 보상 형태도 자율적으로 정할 수 있다"]]}],"7":[{"t":"vs","title":"발명자주의와 사용자주의","cols":[{"name":"발명자주의","items":["우리나라 특허법은 발명자주의를 취해 직무발명이라도 특허를 받을 수 있는 권리는 원칙적으로 발명자인 종업원에게 귀속된다","한국·일본·독일·미국이 채택","권리가 발명자에게 귀속되어 보상규정이 필요하고 대가를 보상이라 한다"]},{"name":"사용자주의","items":["영국·프랑스·네덜란드가 채택","사용자에게 귀속되어 보상규정이 불필요하고 대가를 포상이라 한다"]}]},{"t":"def","term":"조건부 사용자주의","text":"발명진흥법 개정으로 계약이나 근무규정에서 정한 경우 발명을 완성한 때부터 사용자등에게 권리가 귀속되므로 우리나라도 조건부 사용자주의로 전환했다고 볼 수 있다"}],"8":[{"t":"vs","title":"종업원과 사용자의 권리·의무","cols":[{"name":"종업원","items":["권리로는 특허를 받을 권리 내지 특허권의 취득, 발명자로서의 인격권, 정당한 보상을 받을 권리, 조정신청권이 있다","의무로는 협력의무, 고지의무, 비밀유지의무가 있다","사전예약승계규정에 반하여 종업원이 본인 명의로 특허를 출원하면 업무상배임죄에 해당할 수 있다","비밀유지의무는 사용자등이 직무발명을 출원할 때까지이지만, 사용자등이 승계하지 않기로 확정된 경우에는 적용되지 않는다"]},{"name":"사용자","items":["권리로는 통상실시권 취득, 승계취득 또는 전용실시권 설정 권리, 조정신청권이 있다","의무로는 승계예약을 정하지 않은 경우 승계 여부를 통지할 의무와 정당한 보상을 해 줄 의무가 있다","종업원등의 직무발명이 제3자와 공동으로 이루어졌을 때 사용자등이 권리를 승계하면 사용자등은 종업원등이 가지는 권리의 지분을 갖는다"]}]},{"t":"table","title":"승계예약","head":["구분","내용"],"rows":[["승계예약이 있는 경우","계약이나 근무규정으로 승계예약을 정한 경우 직무발명 권리는 발명을 완성한 때 사용자에게 승계된 것으로 본다 · 승계예약이 있어도 사용자가 정해진 기간 안에 권리를 승계하지 않겠다고 종업원에게 통지하면 그 직무발명 권리는 승계되지 않는다"],["예약승계규정이 없는 경우","예약승계규정이 없는 사용자등이 4개월 이내에 승계 여부를 알리지 않으면 승계를 포기한 것으로 보고, 종업원의 동의 없이는 통상실시권도 가질 수 없다"],["표준모델","보상규정 표준모델에서는 직무발명 완성 시 지체 없이 서류를 특허관리전담부서장에게 제출하고, 회사는 직무발명 해당 여부와 승계 여부를 결정해 신고서 제출일부터 4개월 이내에 통지한다"],["심의위원회 자문위원","심의위원회에 자문위원으로 참여하거나 참여했던 사람은 직무상 알게 된 직무발명 내용을 다른 사람에게 누설해서는 안 된다"]]}],"9":[{"t":"table","title":"조정과 심의위원회","head":["구분","내용"],"rows":[["조정 신청","직무발명과 관련해 분쟁이 생기면 종업원등은 산업재산권분쟁조정위원회에 조정을 신청할 수 있고, 사용자등도 조정 신청권을 가진다 · 사용자등이 신청하는 조정과 종업원등이 신청하는 조정은 모두 산업재산권분쟁조정위원회에 한다"],["직무발명심의위원회","사용자등은 직무발명에 관한 규정의 작성·변경, 권리·보상 등에 관한 이견 조정 등을 심의하기 위해 직무발명심의위원회를 설치·운영할 수 있다 · 사용자등과 종업원등(법인의 임원 제외)을 각각 대표하는 같은 수의 위원으로 구성하되, 필요하면 전문가를 자문위원으로 위촉할 수 있다 · 정부는 사용자등의 요청에 따라 관련 분야의 전문가를 자문위원으로 파견할 수 있다"]]},{"t":"flow","title":"심의 절차","steps":["종업원등은 직무발명인지 여부, 보상규정, 보상액 등 직무발명의 권리와 보상에 관해 사용자등과 이견이 있으면 심의위원회 구성과 심의를 요구할 수 있다","종업원등은 심의 요구 사유가 발생한 날부터 30일 이내에 권리를 행사해야 하며, 사용자등이 통지한 보상액에 이견이 있는 경우에는 통지받은 날부터 30일 이내이다","사용자등은 종업원등의 요구를 받으면 60일 이내에 심의위원회를 구성해 심의하게 해야 하며, 이때 직무발명 분야 전문가인 자문위원이 1명 이상 포함되어야 한다","심의위원회는 심의 결과를 사용자등과 종업원등에게 지체 없이 서면으로 통지해야 하며, 결과에 불복하면 산업재산권분쟁조정위원회에 조정을 신청할 수 있다"]},{"t":"table","title":"표준모델의 심의위원회","head":["구분","내용"],"rows":[["구성","표준모델의 심의위원회는 사용자위원과 종업원위원을 같은 수로 구성하며 각각 3명 이상으로 하고, 종업원위원은 종업원등이 직접·비밀·무기명 투표로 선출한다"],["위원장","표준모델에서 위원장은 사용자위원과 종업원위원 중에서 호선하며, 사용자위원과 종업원위원 각각 1명을 공동위원장으로 할 수 있다"],["회의","위원장은 회의 개최 15일 전에 일시, 장소, 의제 등을 각 위원에게 알리며, 회의는 사용자위원과 종업원위원의 각 과반수 출석으로 개의하고 출석위원 과반수 찬성으로 의결한다"]]}],"10":[{"t":"flow","title":"공공연구기관의 권리포기","steps":["공공연구기관이 종업원등으로부터 승계한 직무발명 권리를 포기하는 경우 해당 직무발명을 완성한 모든 종업원등은 그 권리를 양수할 수 있다","공공연구기관의 포기 통지를 받은 종업원등이 권리를 양수하려면 통지받은 날부터 대통령령으로 정한 기간 안에 양수 의사를 기관의 장에게 서면으로 알려야 한다","종업원등이 양수 의사를 알리면 의사표시 기간이 끝난 날의 다음 날부터 그 권리가 종업원등에게 양도된 것으로 본다","양수 의사를 알린 종업원등이 2명 이상인 경우에는 그 권리를 공유한다","공공연구기관의 장은 권리가 종업원등에게 양도된 것으로 보는 날 이후 그 권리와 관련해 발생하는 비용(세금 포함)을 종업원등에게 청구할 수 있다"]}],"11":[{"t":"table","title":"표준모델 운영규정","head":["구분","내용"],"rows":[["출원하지 않는 경우","표준모델에서 회사는 직무발명을 비밀로 유지하는 것이 적합하다고 판단하면 출원하지 않을 수 있으며, 이때 그 이유를 발명자와 소속 부서장에게 서면으로 통지한다"],["비용 부담","표준모델에서 회사는 직무발명의 출원과 권리유지에 드는 비용을 부담하며, 제3자와 공동발명인 경우 그 지분에 따라 부담한다"],["보상금의 종류","표준모델의 보상금은 출원·등록·출원유보 보상금과 직접 실시로 수익이 생길 때의 실시보상금, 양도·실시허락 수익에 따른 처분보상금으로 나뉜다"],["해외 출원","동일한 발명에 대해 여러 국가에 해외 출원이 있는 경우 출원·등록보상금은 최초로 출원된 1국과 최초로 등록된 1국에 대해서만 지급한다"],["비금전적 보상","회사는 발명자가 신청하면 심의위원회 심의를 거쳐 보상금 지급 대신 휴가·승진·승급·연수 등의 비금전적 보상을 할 수 있다"],["공동발명자","공동발명자가 2인 이상이면 신고서에 기재한 지분에 따라 보상금을 나누고, 지분이 기재되지 않았으면 지분이 균등한 것으로 본다"],["보상금 반환","이미 지급받은 보상금은 직무발명 권리가 무효로 된 경우에도 반환하지 않는 것이 원칙이나, 특허법 제33조 제1항 본문 위반 사유로 무효가 된 경우에는 반환 대상이 된다"],["보상규정 변경","보상규정을 변경하려면 적용일 15일 전까지 내용을 서면으로 알리고 종업원등 과반수와 협의해야 하며, 종업원에게 불리하게 바꾸려면 과반수의 동의를 얻어야 한다 · 보상관련규정 중 발명진흥법상 직무발명에 관하여 규정된 내용에 위반하는 부분은 무효이다"]]}],"12":[{"t":"table","title":"발명평가 기준","head":["항목","배점"],"rows":[["기술성, 실시가능성, 독창성, 경제적 가치","각 20점 만점이고 독점성과 기술의 수명은 각 10점 만점이다"],["경제적 가치","연간 매출이 50억 원 이상으로 예상되는 발명은 경제적 가치 항목에서 만점인 20점을 받는다"],["기술의 수명","기술의 수명이 10년 이상으로 보이면 기술의 수명 항목에서 10점 만점을 부여한다"],["독점성","완전한 독점이 가능한 경우에 10점을 부여하고, 공유권리자나 무상 실시권자가 있으면 6점으로 낮아진다"]]},{"t":"axis","title":"발명평가 합계","left":"45점 이상","right":"80점 이상","marks":[{"at":0,"name":"45점 이상: 회사가 발명을 승계하되 국내출원 여부는 이 점수만으로는 결정되지 않는다"},{"at":100,"name":"80점 이상: 승계와 국내출원은 물론 해외출원까지 진행"}]}],"13":[{"t":"table","title":"보상금 산정식","head":["보상","산정"],"rows":[["출원·등록·출원유보 보상금","직무발명 보상 기준표에는 출원보상금, 등록보상금, 출원유보보상금이 있고, 특허·실용신안·디자인별로 금액을 정한다 · 출원유보보상금은 회사가 직무발명을 승계하고도 출원하지 않고 노하우 등으로 보유하기로 한 경우를 위한 보상이며, 국내와 해외를 구분하지 않고 한 금액으로 정한다"],["실시보상금","회사가 직무발명을 직접 실시하는 경우의 실시보상금은 사용자가 얻을 이익에 발명자 공헌도와 공동발명자 중 발명자 기여도를 곱하여 산정한다 · 사용자가 얻을 이익은 매출액에 독점권 기여도와 실시료율을 곱하여 계산하고, 필요하면 발명의 기여도도 곱한다"],["처분보상금","직무발명의 권리를 제3자에게 양도하는 처분보상은 양도대금에 발명자 공헌도와 공동발명자 중 발명자 기여도를 곱하여 산정한다 · 직무발명에 전용실시권이나 통상실시권을 설정하여 회사가 받은 실시료 수입액이 처분보상금 산정의 출발점이 된다"],["결정","기준표에 따른 직무발명 보상액은 심의위원회의 심의를 거쳐 결정한다"]]},{"t":"tree","title":"산정 요소","root":"보상금 산정 요소","branches":[["독점권 기여도","직무발명 덕분에 타인의 발명 실시를 금지하여 얻는 독점적 이익의 비율을 뜻한다"],["발명자 공헌도","발명자의 업무 내용, 회사의 투자 비용, 연구 환경, 특허·사업화 비용 등을 고려하여 발명자가 직무발명에 기여한 비율을 말한다"],["공동발명자 중 발명자 기여도","공동발명자 가운데 해당 발명자의 지분 비율로 본다"]]}],"14":[{"t":"table","title":"직무발명 서식","head":["서식","내용"],"rows":[["발명신고서","발명자별 지분, 발명의 공개 여부와 계획, 직무발명인지 개인발명인지의 구분, 발명의 현단계 등을 적는다 · 발명자 대표가 작성하여 회사의 특허관리전담부서장에게 제출하고, 발명설명서를 함께 첨부한다"],["발명설명서","발명의 명칭, 도면의 간단한 설명, 발명의 상세한 설명, 청구범위, 도면의 순으로 구성된다 · 상세한 설명에는 기술분야, 배경기술, 해결하려는 과제와 해결수단, 발명의 효과, 구체적인 실시예 등을 적는다"],["직무발명 및 승계 여부 결정 통지서","직무발명에 해당하는지와 회사가 권리를 승계하는지에 대한 결정이 담기며, 특허관리전담부서장이 발송한다"],["양도증","발명자(양도인)가 특허 등을 받을 수 있는 권리를 회사(양수인)에 넘긴다는 뜻을 밝히는 서식이다 · 양도인별 지분율을 적으며, 양수인란에는 회사와 그 대표이사를 적는다"],["출원 통지서","출원 여부와 출원일자·출원번호를 적고, 출원하지 않았다면 그 이유를 밝혀 발명자에게 알린다"],["심의요구서","보상 등에 불복하는 발명자가 직무발명심의위원회 위원장에게 내는 서식이며, 사유가 생긴 날짜와 증거서류를 함께 제출한다"],["심의결과 통지서","심의요구의 취지와 이유, 심의위원회의 결정 취지와 이유를 적으며, 직무발명심의위원회 위원장 명의로 보낸다"]]}],"15":[{"t":"def","term":"IP 분쟁 예방 및 대비 전략","text":"기업이 지식재산권을 보호하고 활용하기 위해 사전에 준비하는 일련의 계획과 조치를 뜻한다","ex":["분쟁 예방을 위해 기업은 정기적으로 시장을 모니터링하여 침해 사례를 신속히 찾아내고, 타사의 지식재산권을 분석해 자사 기술이 타인의 권리를 침해하지 않는지 사전에 확인할 수 있다"]},{"t":"tree","title":"IP 분쟁 예방 마인드맵","root":"IP 분쟁 예방 마인드맵의 구성 요소","branches":[["시장 동향 모니터링","시장 동향 모니터링"],["관련 특허조사","관련 특허조사"],["명확한 라이선스 계약","명확한 라이선스 계약"],["자사 권리의 적극적 확보","자사 권리의 적극적 확보"],["전문인력 확보","전문인력 확보"],["대응 매뉴얼 정비","대응 매뉴얼 정비"]]},{"t":"table","title":"특허 감시","head":["구분","내용"],"rows":[["침해 분쟁 대비","침해 분쟁에 대비하려면 경쟁사뿐 아니라 NPE가 보유한 특허도 상시 감시·분석하여 문제될 특허의 대응책을 마련해 두는 것이 바람직하다 · 경쟁사 특허의 감시와 분석은 사내 전담 인력이 수행할 수도 있고 외부 전문가에게 맡길 수도 있다"],["특허 모니터링(와칭)","사업 확장이나 신규 연구개발 시 문제될 특허가 있는지 확인하기 위해 경쟁사의 특허 동향을 지속적으로 파악하는 활동이다 · 특허 감시를 하면 경쟁사의 기술 개발 방향과 트렌드를 파악하여 자사 연구개발 전략에 활용할 수 있다"],["문제될 수 있는 특허 발견","엔지니어와 협의해 회피설계를 마련하거나 무효자료를 조사해 변리사에게 감정서나 보고서를 의뢰한다 · 법률 의견서(legal opinion)는 해당 특허권이 등록된 국가의 변리사나 변호사로부터 받는 것이 바람직하다"]]},{"t":"flow","title":"문제 특허에 대한 대응","steps":["문제의 특허가 공개되었으나 아직 등록되지 않았다면 정보 제공을 통해 특허등록을 저지하는 것이 바람직하다","이미 등록된 특허는 설정등록일로부터 등록공고일 후 6개월까지는 이해관계와 상관없이 누구나 특허 취소 신청을 할 수 있다","취소 신청 기간이 지난 뒤에는 이해관계를 소명하여 무효심판을 청구할 수 있으나, 당사자로서 특허권자에게 드러나 오히려 침해 소송 등의 공격을 받을 수 있다"]}],"16":[{"t":"table","title":"특허 포트폴리오","head":["기업","내용"],"rows":[["웨이모","인수합병으로 자율주행 분야의 특허 포트폴리오를 넓히고 전략적으로 중요한 특허를 선택적으로 인수하여 기술적 우위를 유지했다"],["삼성전자","강력한 특허 포트폴리오를 바탕으로 경쟁사와의 소송과 협상에서 우위를 점하고, 크로스 라이선스로 침해 소송 위험을 줄인다"],["애플","아이폰의 외관을 디자인 특허로, 센서·배터리·Face ID 같은 기능을 기술 특허로 보호하며 모방 제품에 특허침해소송으로 대응한다"]]},{"t":"def","term":"크로스 라이선스 계약","text":"두 기업이 서로의 특허를 상대방이 쓸 수 있게 허용하는 계약이다","ex":["특허권을 확보해 두면 분쟁이 생겼을 때 크로스 라이선스를 맺거나 침해소송을 제기한 상대방에게 반소로 맞설 수 있다"]}],"17":[{"t":"flow","title":"해외 출원","steps":["산업재산권은 속지주의 원칙에 따라 등록한 국가 안에서만 효력이 있으므로, 사업을 하려는 나라마다 별도로 권리를 확보해야 한다","파리조약에 따라 제1국에 출원한 뒤 1년 이내에 우선권을 주장하며 다른 가입국에 출원하면, 특허성 판단 시점이 제1국 출원일로 소급된다","PCT 제도로 출원하면 모든 가입국에 출원한 것으로 간주되며, 대개 우선일로부터 30개월 또는 31개월 안에 실제로 권리를 원하는 국가에 국내단계로 진입한다"]},{"t":"table","title":"해외 출원 비용·심사","head":["구분","내용"],"rows":[["출원 유지료","유럽 등 일부 국가는 한국과 달리 출원 상태에서도 출원 유지료를 매년 관납료로 내야 한다"],["가속 심사 제도","권리화를 앞당기는 가속 심사 제도로는 특허심사 하이웨이(PPH), 유럽의 PACE, 미국의 Track 1 등이 있다"]]}],"18":[{"t":"table","title":"계약에 의한 보호","head":["계약","내용"],"rows":[["계약에 의한 기술 보호","다양한 제한 조건을 붙일 수 있다는 장점이 있지만 계약 당사자에게만 효력이 미친다"],["부제소특약(Covenant Not to Sue)","한쪽 당사자가 상대방을 상대로 소송을 제기하지 않겠다고 약속하는 계약이다"],["라이선스 계약","기술을 사용할 권리를 주면서 사용 조건을 제한하거나 특정 방식으로만 쓰도록 요구할 수 있는 계약이다"],["비밀유지계약(NDA)","둘 이상의 당사자가 정보를 공유할 때 이를 제3자에게 누설하지 않겠다고 약속하는 계약으로, 보통 사업이나 협력을 시작하기 전에 체결한다"]]},{"t":"tree","title":"NDA","root":"비밀유지계약(NDA)","branches":[["담는 내용","비밀로 유지할 정보의 범위, 비밀 유지 기간, 비밀 정보의 취급 지침, 누설 시의 법적 책임과 제재를 담는다"],["비밀 유지 기간","협력이 끝난 뒤에도 일정 기간 비밀을 지키도록 정할 수 있다"],["공지예외주장","특허출원 전에 협상 중이던 기술 자료가 뜻하지 않게 공개되었을 때, NDA를 체결해 두었다면 공지예외주장 제도를 이용하는 데 도움이 될 수 있다"]]}],"19":[{"t":"table","title":"증거 관리","head":["제도","내용"],"rows":[["증거개시(discovery)제도","미국 민사소송규칙(FRCP)에서 소송 당사자가 관련 자료를 의무적으로 제출해야 하며, 이를 다하지 못하면 법원의 제재나 패소를 당할 수 있다"],["데이터 보존 정책(DRP)","관리 대상, 목적, 관리 주체, 관리 형태, 접근 권한, 자료의 보존 및 폐기 등이 포함되며 문서화하여 지켜야 한다"],["기술임치제도","중요한 기술자료를 중립적인 제3의 기관에 맡기고 그 자료의 특정 날짜 존재를 증명받는 제도이다 · 자료의 기밀성을 유지하면서 법적 효력이 있는 증거로 쓸 수 있고, 자료의 유출이나 손실도 막을 수 있다"],["인터넷 아카이브","웹상 자료가 과거 어느 시점부터 존재했는지 입증하기 어려울 때는 미국 비영리단체 인터넷 아카이브에 내용을 저장하여 게재일을 입증하는 방법이 있다"]]}],"20":[{"t":"vs","title":"보증·면책 요구","cols":[{"name":"공급받는 쪽","items":["물품이나 기술을 공급받는 쪽은 특허 침해가 발생할 때를 대비한 보증 조항을 계약에 넣기를 원한다"]},{"name":"공급하는 쪽","items":["소송 위험을 최소화하려 한다","공급자는 공급받는 자의 요구에 따라 채택된 제품이나 기술에 대해서는 특허 침해 문제가 생겨도 책임이 없다는 제한 조항을 넣는 것이 바람직하다","공급자는 FTO(실시자유) 검토를 최종 제품이 완성된 뒤가 아니라 제품 설계 단계부터 매년 수행해 두는 것이 보증 계약에서 유리하다"]}]},{"t":"def","term":"보증·면책 요구","text":"계약 체결 시 한쪽 당사자가 다른 쪽에게 특정 조건이나 상황에서 법적 책임을 지지 않도록 요구하는 것을 뜻한다","ex":["보증·면책 외 대안으로는 공급자 비용으로 계속 사용할 권리(라이선스) 확보, 대체품 사용 요구, 기술 개선 요구, 제3자 권리 침해 사실의 상호 통지 의무 부과 등이 있다","계약에 공동방어 의무를 규정하면 제3자의 침해 문제에 양측이 함께 대응하도록 할 수 있다"]}],"21":[{"t":"cause","title":"해외 전시회 위험","causes":["독일 등의 해외 전시회에서는 지식재산권 침해 문제로 제품이나 홍보 자료가 압수되거나 전시회 참가 자체가 거부되기도 한다"],"result":"해외 전시회 참가 전에는 전시 국가에 관련 지식재산권을 미리 등록하고, 경쟁사 특허를 조사하여 침해 가능성을 파악해야 한다","effects":["독일 전시회에서는 가압류나 가처분이 전시자 의견 청취 없이 진행되는 일이 많아, 비침해나 무효를 주장하는 방어서면(protective brief)을 미리 관할 법원에 제출해 두는 것이 좋다","전시회 중에는 자사 제품에 대한 정보를 과도하게 제공하지 않도록 주의하고, 카탈로그나 홍보물에는 지식재산권 표시를 명확히 해야 한다"]}],"22":[{"t":"flow","title":"특허 분쟁의 순서","steps":["경고장 수령","특허 분석","대응 전략 수립","경고장 회신","협상·라이선싱 시도","소송"]},{"t":"table","title":"침해 주장이 타당한 경우","head":["대응","내용"],"rows":[["사용 중지","침해 주장이 타당하다고 판단되면 먼저 해당 기술이나 제품의 사용을 중지해야 하지만, 이미 이루어진 과거 사용에 대한 손해배상 책임은 여전히 남는다"],["회피설계","청구항의 구성요소 일부를 쓰지 않거나 다른 것으로 대체하도록 제품이나 기술의 설계를 바꾸는 전략이며, 균등 범위의 침해 여부를 충분히 사전 검토해야 한다"],["제3자 특허 활용","특허권자가 실제로 쓰는 제품이 침해할 수 있는 다른 특허를 제3자가 갖고 있다면, 그 특허를 매입하거나 전용실시권을 설정하여 협상 카드로 쓸 수 있다"],["라이선스와 매입","라이선스 계약은 특허권자의 허가를 받아 조건부로 기술을 쓰는 것이고, 특허 매입은 특허를 완전히 소유하여 독점적으로 쓰는 것이다"],["크로스 라이선스","자사에 대응특허가 있다면 이를 활용해 상대방과 크로스 라이선스를 체결함으로써 서로의 특허를 사용할 수 있게 하여 분쟁을 해결할 수 있다"]]},{"t":"table","title":"침해 주장이 부당한 경우","head":["구분","내용"],"rows":[["기본 방침","침해 주장이 부당하다고 판단되면, 소송으로 갈 것인지 협상으로 해결할 것인지 기본 방침을 먼저 정해야 일관되고 효과적인 대응이 가능하다 · 기본 방침을 정할 때는 상대방의 의도, 특허의 유효성, 자사 전체 사업에 미칠 영향, 소송과 협상의 기회비용을 함께 따져야 한다"],["상대방","비실시기업은 주로 실시료 수입을 위해 협상에 적극적이어서 의도를 파악하기 쉽고, 경쟁사는 라이선스 수익을 원하는지 시장에서 퇴출시키려는지를 따로 파악해야 한다 · 제품을 생산하지 않는 비실시기업과의 분쟁에서는 크로스 라이선스가 성립할 가능성이 거의 없다는 점을 고려해야 한다"],["청구범위 분석","청구범위 분석 결과 비침해·무효·행사 불능의 가능성이 희박하면 협상으로 라이선스를 취득하는 것이 바람직하고, 가능성이 충분하면 적극적으로 소송에 대응할 수 있다"],["전문가 의견","비침해나 무효 여부는 최종적으로 법원이 판단하므로 전문 변호사·변리사의 의견을 증거로 확보해 두어야 하며, 이는 고의 침해를 피하는 데도 도움이 된다"]]}],"23":[{"t":"table","title":"경고장의 성격","head":["구분","내용"],"rows":[["경고장","특허권자가 자신의 특허권을 침해하고 있다고 판단되는 자에게 침해 중지를 요구하는 서면이다"],["고의 침해","경고장을 받은 뒤에도 침해를 계속하면 고의적 침해로 간주될 수 있고, 우리나라에서는 고의 침해로 인정되면 손해배상액이 최대 3배까지 증가할 수 있다"],["소송의 필수 단계가 아님","경고장은 특허침해소송의 필수 단계가 아니므로 특허권자는 경고장 없이 곧바로 소송을 제기할 수도 있다"],["미국","미국 특허소송에서는 특허권자가 제품에 특허 표시를 하지 않은 경우 경고장의 발송 및 수령이 손해액 산정의 기산점이 될 수 있다"],["회신 의무","경고장을 받았다고 반드시 법적으로 회신해야 할 의무는 없고 경고장에 적힌 회신 기한도 특허권자가 임의로 정한 것이어서 법적 구속력이 없다"]]},{"t":"flow","title":"경고장 수령 후 대응","steps":["경고장을 받으면 특허팀이나 법무팀을 중심으로 대응 팀을 꾸리고 외부 전문가를 신속히 선임하며, 미국 분쟁이라면 증거보존 통지(litigation hold)를 발동해 증거를 준비한다","소송 경험이 많은 전문가는 한정적이므로, 상대 측이 이들을 복대리로 모두 선점하면 우리 편에 설 전문가가 부족해질 수 있다","경고장이 침해 특허와 침해 제품을 구체적으로 특정하지 않고 막연하게 작성되었다면, 회신 단계에서 구체적인 특정을 요구해야 한다","경고장을 받으면 발송자가 정당한 권리자인지, 소송을 제기할 권한이 없는 통상실시권자는 아닌지를 확인해야 한다"]},{"t":"table","title":"경고장 발송 주체","head":["주체","의미"],"rows":[["NPE","경고장을 보낸 주체가 NPE라면 주로 라이선스를 통해 수입을 얻으려는 목적으로 이해할 수 있다"],["특허권자 직접","특허권자가 직접 경고장을 보낸 경우는 협상을 통한 라이선스 요구가 많다"],["대리인","대리인을 통해 보낸 경우는 소송을 염두에 두었을 가능성이 높다"],["협박에 가까운 기재","경고장이 근거 없이 침해 사실과 손해배상액을 사실인 양 협박에 가깝게 기재했다면 영업방해로 거꾸로 손해배상 청구를 당할 수 있다"]]}],"24":[{"t":"vs","title":"경고장 대응 흐름","cols":[{"name":"침해로 판단","items":["실시중지, 회피설계, 무효화, 화해·라이선스, 대응 특허 매입, 역 경고 전략을 고려한다"]},{"name":"비침해로 판단","items":["답변서로 해명하거나 권리범위확인심판(소극)을 청구한다"]}]},{"t":"table","title":"유효성과 침해 검토","head":["구분","내용"],"rows":[["특허권 유효성","침해를 주장하는 특허권이 유효한지 보려면 유지료가 정당하게 납부되었는지, 경고장 발송자가 실제 특허권자나 전용실시권자인지를 확인한다"],["존속기간","국가별로 존속기간을 늘려주는 제도가 있으므로 특허 만료일은 출원일로부터 20년으로 단순 계산하지 말고 국가별 법규를 확인해야 한다"],["침해 여부 판단","자사 제품의 침해 여부를 판단할 때는 구성요소 완비의 법칙, 균등론, 간접침해, 자유기술 항변, 권리 소진, 출원경과 금반언의 원칙 등을 검토한다"]]},{"t":"vs","title":"무효 절차","cols":[{"name":"한국, 중국, 대만, 일본, 독일 등","items":["무효화 절차와 침해 소송 절차가 별도로 진행되므로 침해 주장을 받은 자가 무효심판을 청구하는 것이 효과적이다"]},{"name":"미국","items":["특허 무효가 연방 지방법원 침해 소송에서 함께 다뤄지며, 피고는 특허청 특허심판항소위원회(PTAB)에 당사자계 재심사(IPR)나 등록 후 재심사(PGR)를 제기할 수 있다","침해 소송이 제기되지 않았더라도 가능성이 높으면 비침해 및 무효 확인 소송(DJ Action)을 제기할 수 있으나, DJ Action을 진행하면 IPR은 중복해서 제기할 수 없다"]}]},{"t":"table","title":"무효 사유","head":["구분","내용"],"rows":[["무효자료","전 세계의 어떤 자료라도 유효하되, 해당 특허의 출원일 이전에 공지된 선행기술이어야 하며 공용 기술이라는 점을 입증할 수도 있다"],["무효 사유","추상적 아이디어나 자연법칙에 불과한 기술을 청구한 경우, 또는 명세서가 기재 요건을 충족하지 못한 기재 불비의 경우에도 특허는 무효화될 수 있다"],["IDS","미국에서 알고 있는 중요한 선행기술을 의도적으로 정보공개명세서(IDS)로 제출하지 않았다면 부정행위로 간주되어 특허권 행사가 제한될 수 있다"],["파라미터 특허","동일한 파라미터의 선행문헌을 찾기 어려워, 출원일 이전 제품에서 같은 기준으로 평가했을 때 파라미터가 도출되는 내재적 특성의 주장이 많다"],["표준특허(SEP)","권리자는 FRAND 선언을 하고 공정하고 합리적이며 비차별적인 조건으로 라이선스를 해 줄 의무가 있다"]]}],"25":[{"t":"vs","title":"소송과 협상","cols":[{"name":"협상","items":["일반적으로 소송은 시간과 비용이 많이 들고 결과를 예측하기 어려워 소송보다 협상으로 분쟁을 해결하는 것이 더 유리하다"]},{"name":"소송","items":["협상으로 해결하기 어렵고 특허권자의 입장이 완강하면 소송이 불가피하며, 적극적으로 대응하면 과도한 실시료를 줄이고 다른 경쟁자들의 이후 소송을 미연에 막을 수 있다","막대한 비용과 시간이 들고 패소하면 사업 철수의 위험이 있으며, 미국에서는 고의 침해로 인정되면 손해배상액이 최대 3배까지 증가할 수 있다"]}]},{"t":"table","title":"가처분","head":["구분","내용"],"rows":[["가처분 소송","특허권자는 침해가 명백하고 신속한 조치가 없으면 회복할 수 없는 손해가 발생한다고 판단될 때 가처분 소송으로 침해 행위를 빠르게 금지할 수 있다"],["가처분의 한계","가처분은 요건이 엄격하여 받아들여질 가능성이 높지 않고, 가처분 결정 후 본안 소송에서 패소하면 그에 따른 손해를 배상해야 할 수도 있다"]]},{"t":"vs","title":"재판 외 분쟁해결(ADR)","cols":[{"name":"중재","items":["당사자들이 합의한 중재인이 법적 구속력 있는 결정을 내린다","보통 비공개로 진행되어 기업의 민감한 정보를 보호할 수 있다"]},{"name":"조정","items":["조정인이 법적 구속력 없는 권고로 당사자의 합의를 돕는다","소송보다 시간과 비용을 줄일 수 있다"]}]}],"26":[{"t":"table","title":"협상 단계","head":["단계","내용"],"rows":[["단계 구분","협상은 크게 사전 협상, 본 협상, 후속 협상으로 나뉘며 본 협상은 다시 기술 협상과 비즈니스 협상으로 구분된다"],["사전 협상","협상을 위한 준비 단계로 상대방 특허의 기술 내용과 강약점, 상대의 협상 스타일을 분석하고 자사의 협상 목표와 양보 범위를 정한다"],["기술 협상","특허 기술의 내용과 활용 방안 및 기술 이전·사용 조건을 논의한다 · 주로 특허권에 대한 침해 여부를 다루며, 특허권자가 침해 사실을 입증하는 한편 침해자로 지목된 측은 비침해나 무효 가능성의 자료로 반박한다 · 경고장을 보낸 자의 특허권도 침해할 수 있다고 주장하여 서로 크로스 라이선스를 제안하는 전략을 쓸 수도 있다"],["비즈니스 협상","로열티, 라이선스 조건, 계약 기간 등 경제적 조건을 논의한다"],["후속 협상","본 협상에서 합의한 사항을 구체화하고 계약서 작성 및 서명 등의 절차를 진행하며, 논의 내용이 제대로 반영되었는지 확인한다"]]},{"t":"tree","title":"협상 준비와 진행","root":"협상 전략","branches":[["목표","협상의 목표가 명확하지 않으면 협상 과정에서 혼란이 생기고 상대방에게 주도권을 빼앗길 수 있으므로 목표를 분명히 하고 이에 맞추어 준비해야 한다"],["협상 팀","협상 준비 단계에서는 협상 팀을 구성하고, 협상 대상이 되는 부분과 양보할 수 있는 부분, 반드시 관철해야 하는 부분을 명확히 정해야 한다"],["갈등","협상 테이블에서 갈등이 생겨도 감정적으로 대응하면 협상 주도권을 상대방에게 넘겨줄 수 있으므로 주의해야 하고, 교착 상태에서는 휴식을 취하며 제3의 대안을 모색하는 것이 좋다"],["협상안","어떤 협상안이든 즉시 수용하는 것은 바람직하지 않으며, 잠정적 합의임을 명시하고 휴식을 가진 뒤 논의를 이어가거나 다음 협상으로 미루는 것이 필요하다"],["최종 결정권자","최종 결정권자의 승인이 필요한 경우가 많으므로 협상 테이블에 대표이사나 최종 결정권을 가진 사람이 직접 임하는 것은 위험할 수 있다"],["기록","협상 테이블에서 논의한 내용은 반드시 기록하고 양 당사자가 협상 종료 시 확인하고 서명하여 교환하는 것이 바람직하며, 비밀유지계약(NDA)을 사전에 체결하는 것도 중요하다"]]}],"27":[{"t":"table","title":"계약서 검토","head":["구분","내용"],"rows":[["기술의 가치평가","계약서를 검토할 때는 기술의 가치평가가 필요하며, 라이선시의 실시료 지불 능력과 기술·제품의 라이프 사이클, 특허권의 존속기간과 권리범위를 고려해야 한다"],["권리범위","권리범위가 넓으면 더 많은 영역에서 보호받을 수 있지만 좁으면 보호 범위가 제한되므로, 계약서 검토 때 권리범위와 기술의 완성도·활용범위를 고려해야 한다"],["크로스 라이선스","서로 다른 기술이나 특허를 가진 두 회사가 서로에게 사용 권리를 주는 것을 의미한다"],["제3자 권리","특허권자와 라이선스 계약을 맺었다고 해서 라이선시가 제3자의 권리로부터 자유로워지는 것은 아니므로, 제3자 특허권 침해 가능성을 미리 검토해야 한다 · 제3자 특허권을 침해할 위험이 있으면 라이선스 계약을 포기하거나, 계약에 라이선서가 제3자 소송을 방어하거나 추가 라이선스를 체결해야 한다는 책임 조항을 넣을 수 있다"]]},{"t":"vs","title":"통상실시권과 전용실시권","cols":[{"name":"통상실시권","items":["여러 사용자에게 동일한 기술을 쓰게 할 수 있는 권리이다","통상실시권자는 제3자의 침해에 대해 직접 소송을 제기할 수 없다"]},{"name":"전용실시권","items":["특정 사용자에게만 독점적으로 사용하게 하는 권리이다","전용실시권자는 제3자가 자신의 전용실시권을 침해하여 특허발명을 사용할 때 소송을 제기할 수 있다","미국에서는 독점적 라이선시가 계약상 제한이 없으면 전용실시권과 유사하게 자신의 권리를 보호하기 위해 소송을 제기할 수 있다"]}]},{"t":"table","title":"라이선스 범위","head":["구분","내용"],"rows":[["범위 명확화","계약서에서 라이선스 범위를 명확히 하려면 실시권의 종류, 지역적·시간적 범위, 유효 기간과 갱신 조건, 사용할 제품의 범위를 정해야 한다"],["사적 자치","계약에 의한 실시권은 사적 자치의 원칙에 따라 기간, 지역, 제품·형태 등 다양한 조건과 제한을 둘 수 있다"],["양도·재실시권","한국에서는 특허권자의 동의 없이 사용 권리를 타인에게 넘기거나 재실시권을 설정하는 것이 일반적으로 불가능하지만, 중국에서는 계약에 특별한 제한이 없으면 자유롭게 양도하거나 재실시권을 설정할 수 있다 · 라이선스 계약서에는 양도 가능 여부, 재실시권 설정 가능 여부, 그리고 특허권자의 사전 동의 등 특별한 조건을 명시해야 한다"]]}],"28":[{"t":"table","title":"소송 개시와 송달","head":["구분","내용"],"rows":[["소송이 불가피한 경우","협상이 결렬되거나 특허권자가 실시료 수입이 아닌 침해 금지를 원하거나, 침해를 주장받은 자가 라이선스보다 비침해·무효로 권리 행사를 저지하려는 경우에는 소송이 불가피하다"],["한국의 소장","한국에서는 특허권자가 법원에 소장을 제출하는 순간 소송이 시작되고 법원이 직접 소장을 송달한다"],["미국의 소장","미국에서는 소장을 제출한 원고가 직접 송달해야 한다 · 피고의 주소가 한국에만 있으면 소장 송달에 최소 2~3개월이 걸릴 수 있어, 이 시간제 지연 동안 원고가 협상을 제안하는 경우도 있다"],["답변서","원고가 소송을 제기해 소장이 송달되면 피고는 답변서를 제출해야 하는데, 제출 기한은 국가마다 다르며 일부 국가는 매우 짧은 기한을 둔다"]]},{"t":"vs","title":"피고의 대응","cols":[{"name":"소극적 대응","items":["원고의 주장을 반박하고 특허 침해가 발생하지 않았다는 증거를 수집·제출하는 것이다"]},{"name":"적극적 대응","items":["특허권의 하자와 무효 사유를 입증하는 것이며, 대표적인 방법이 무효심판이다","무효심판에서 특허가 무효로 확정되면 해당 특허침해소송은 다툴 대상이 없어져 법원이 이를 각하할 수밖에 없다"]}]},{"t":"table","title":"심판과 재심사","head":["구분","내용"],"rows":[["소극적 권리범위확인심판","피고가 쓰는 기술이 원고의 특정 특허권 범위에 속하지 않는다는 판단을 받기 위해 특허심판원에 청구하는 심판이다 · 승소하더라도 그 결정이 법원을 절대적으로 구속하지는 않으므로 침해 소송에서 유리한 증거로 쓸 수는 있어도 법원이 반드시 따라야 하는 것은 아니다"],["중국, 대만, 일본, 독일 등 유럽","한국처럼 침해 소송과 무효심판 절차가 별도로 진행되어, 침해 소송 중에도 무효심판이 따로 다뤄질 수 있다"],["미국 PGR·IPR","미국에서는 특허가 등록된 후 9개월 이내에 등록 후 재심사(PGR)를 청구할 수 있고, 9개월이 지난 특허는 당사자계 재심사(IPR)로 무효를 다툴 수 있다"],["비침해 및 무효확인소송","미국에서 특허권자의 침해 소송이 제기되기 전에 대응하려면 일정 요건을 갖춰 비침해 및 무효확인소송(Declaratory Judgment Action)을 제기해 침해 여부와 특허 유효성을 사전에 판단받을 수 있다"]]}],"29":[{"t":"table","title":"침해 증거 수집","head":["구분","내용"],"rows":[["침해 정보","특허공보 정기 모니터링, 경쟁사 홈페이지·카탈로그·매뉴얼 조사, 신문·박람회 조사, 거래선 조사 등으로 얻을 수 있으며, 방법이 위법하면 증거력에 문제가 생길 수 있다"],["침해 입증","공격자는 침해 입증을 위해 최소 두 개 이상의 침해 제품을 구입해 분해하거나 완제품 상태로 보관하고, 영수증을 보관해 침해 시점과 출처를 증명할 수 있게 해야 한다"],["손해배상","손해배상을 위해서는 침해로 인한 매출 손실이나 시장점유율 하락 등을 입증할 자료를 수집하고, 침해 입증이 어려우면 전문 분석기관의 분석 보고서를 확보한다"],["침해 분석 단계","심사 포대와 등록 청구항 검토, 침해 여부 및 자사 특허 무효 여부 분석, 침해자의 회피설계 검토, 필요시 전문가 감정을 수행한다"],["침해자 분석","사업 분야, 매출 규모와 특허 현황, 과거 분쟁과 소송 이력, 자본 현황을 조사하여 상대의 시장 영향력과 법적 대응 성향·재정 능력을 평가한다"]]},{"t":"flow","title":"등록된 특허의 공격 전략","steps":["특허권자인 공격자는 먼저 해당 특허가 정식으로 등록되어 있는지 확인해야 하며, 등록 여부에 따라 대응 방법이 달라진다","침해 제품 분석","경고장 발송 · 어떤 부분이 특허를 침해했는지와 침해 중지 요구가 담기며, 법적 절차를 밟기 전에 분쟁을 해결할 수 있는 첫 단계이다","협상 및 라이선스 제안","소송 제기","법적 판결"]},{"t":"table","title":"출원 중인 경우와 무효 대비","head":["구분","내용"],"rows":[["경고장","출원이 진행 중이면 현재 실시 중인 발명이 출원 중인 발명이며 특허 등록 시 보상금 청구 대상이 될 수 있다는 내용의 경고장을 보내 손해배상 청구 기간을 늘릴 수 있다 · 출원 진행 중인 발명을 상대가 쓰고 있다면, 등록 시 보상금 청구 대상이 될 수 있음을 알리는 경고장을 보내 두는 것이 좋다"],["우선심사·조기 공개","출원 중인 공격자는 제3자의 실시를 이유로 우선심사를 신청해 등록을 최대한 빨리 유도할 수 있으며, 보상금 청구권 발생을 위해 조기 공개 신청도 함께 고려할 수 있다"],["무효 대비","공격자는 자사 특허가 무효화될 가능성에 대비해 필요하면 분할 출원이나 신규 출원을 진행하여 계속 심사 중인 출원을 남겨 둘 수 있다"]]}],"30":[{"t":"table","title":"권리 행사","head":["구분","내용"],"rows":[["등록 여부","저작권이나 영업비밀은 예외적으로 등록 없이도 권리를 행사할 수 있고, 대부분의 다른 지식재산권은 등록을 통해 보호받는다"],["특허권의 보호범위","특허법에 따라 청구범위에 기재된 내용으로 명확히 정해져 권리자와 제3자 모두에게 예측 가능성을 준다"],["침해 알고도 미룸","침해를 알고도 조치를 미루면 침해를 묵인한 것으로 오해받을 수 있고, 심하면 법적으로 권리 행사를 포기한 것으로 간주될 수 있다"],["지식재산권 표시","제품에 지식재산권 보유 사실을 명확히 표시하면 잠재적 침해자에게 경고가 되어 무단 사용이나 복제를 억제하는 효과가 있다"]]},{"t":"table","title":"침해 대응","head":["구분","내용"],"rows":[["소송 외 방법","소송은 시간과 비용이 많이 들고 결과 예측도 어려우므로 직접 협상, 라이선스 체결, 기술적 보호 조치, 교육 같은 방법도 함께 고려한다"],["대응 전략","침해 대응 전략을 세울 때는 침해자의 협상 의사, 침해 중지 요구 또는 대가 수용 여부, 자사의 법적 대응 능력, 시장 점유율, 소송 외 해결 가능성 등을 따진다"],["제소할 수 있는 사람","특허나 등록디자인 소송에서 침해를 이유로 제소할 수 있는 사람은 특허권자나 전용실시권자이고, 통상실시권자의 제소는 허용되지 않는다"],["소멸한 권리","존속기간이 이미 만료되었거나 유지료 미납으로 소멸한 권리를 근거로 한 제소는 법적 근거가 없으므로 권리가 유효한지 먼저 확인해야 한다"],["승소","침해소송에서 승소하면 피해 보상과 함께 침해 행위를 중단시키는 금지 명령을 얻을 수 있고, 고의적 침해에는 형사 처벌도 가능하다"],["과실 추정","특허법은 특허의 무형적 특성으로 침해 입증이 어렵다는 점을 고려해 침해자의 과실을 법률상 추정하는 규정을 두고 있다"]]}],"31":[{"t":"table","title":"정보제공제도","head":["구분","내용"],"rows":[["정보제공제도","특허가 공개되었으나 아직 등록결정이 나지 않은 출원에 대해 선행기술 정보를 특허청에 제출하는 제도이다"],["제공 방법","특허법 제63조의2에 따라 누구든지 거절 이유에 해당해 특허될 수 없다는 취지의 정보를 증거와 함께 특허청장에게 제공할 수 있다"],["익명·통지","정보제공은 익명으로도 제출할 수 있으며, 심사관은 정보제출서가 이송된 날부터 1개월 이내에 정보제공 사실을 출원인에게 통지해야 한다"],["효력","정보제공에는 법적 강제성이 없지만 담당 심사관은 보통 제공된 정보를 심사에 참고하고 활용 결과를 통보한다"]]},{"t":"vs","title":"무효심판과 소극적 권리범위확인심판","cols":[{"name":"특허무효심판","items":["특허권자로부터 경고를 받은 자, 동종 업종 종사자, 특허권 존속에 이해관계가 있음을 입증한 자가 청구할 수 있다","특허청 소속 준사법기관인 특허심판원에 제기하며, 특허권이 소멸한 후에도 청구할 수 있다"]},{"name":"소극적 권리범위확인심판","items":["자신이 실시하는 기술이 특허권자의 특허 권리범위에 속하지 않음을 공식적으로 확인받기 위해 청구한다","특허권자를 상대로 특허심판원에 청구하며, 청구인이 자신의 실시 기술을 구체적으로 특정해 제시해야 한다"]}]}],"32":[{"t":"table","title":"실시 중단과 실시권 확보","head":["구분","내용"],"rows":[["선사용권","타인의 특허출원 이전부터 그 발명을 국내에서 실시하거나 준비하던 자는 선사용에 의한 통상실시권을 주장할 수 있다"],["권리범위에 속하는 경우","자신의 실시 기술이 상대 특허의 권리범위에 속한다고 판단되면 먼저 실시를 즉시 중단하고 특허권자와 협의해 실시권을 얻거나 특허권을 양도받아야 한다"],["크로스 라이선스","상대 기술에 대응할 개량특허권을 보유하고 있다면 서로의 특허를 허락하는 크로스 라이선스 협상이 양측에 유리한 해결책이 될 수 있다"],["통상실시권 허락심판","자신의 특허를 실시하려면 상대 특허도 써야 하는 이용관계에서 정당한 대가를 제시했는데도 허락받지 못하면 특허심판원에 통상실시권 허락심판을 청구할 수 있다"]]}],"33":[{"t":"table","title":"미국 소송의 시작","head":["구분","내용"],"rows":[["소장","미국에서는 소장 제기 전에 경고장이 먼저 발송되는 경우가 많고, 원고가 직접 피고에게 소장을 송달하는 점이 한국 절차와 다르다"],["송달","헤이그협약에 따르면 외교 경로를 거치지 않고 한국 법원 행정처를 통해서도 송달이 가능하여 송달 절차를 간소화할 수 있다"],["손해배상 기간","미국에서는 특허 표시가 있거나 경고장 등으로 특허된 제품임을 안 때부터 소급하여 6년간의 손해배상을 청구할 수 있다"],["확인의 소","미국에서 피고는 원고가 소송을 내기 전에 비침해 및 무효를 주장하는 확인의 소를 제기하여 유리한 법원을 고를 기회를 얻을 수 있다"],["답변서·반소","미국 소송에서 피고가 답변서로 소장의 주장을 반박하지 않으면 그 주장을 인정한 것으로 간주된다 · 피고는 필요하면 원고의 특허권 침해나 독점금지법 위반을 주장하는 반소를 제기할 수 있다"]]},{"t":"flow","title":"미국 소송 절차","steps":["피고가 소장을 접수한 때부터 사실심 심리 전 협의를 마칠 때까지를 법원에서는 답변 기간(pleading)이라고 부른다","증거개시 절차는 답변 기간이 끝난 뒤 시작되며, 양 당사자는 소송과 관련된 모든 증거를 제출할 의무가 있다","마크만 히어링은 소송 대상 특허의 청구범위를 명확히 해석하고 확정하는 절차로, 보통 증거개시 절차가 끝난 뒤에 진행된다","약식판결은 핵심 사실관계에 더 이상 다툼이 없을 때 공판을 거치지 않고 판사가 법률적 판단을 내리는 절차이다"]},{"t":"table","title":"증거개시와 약식판결","head":["구분","내용"],"rows":[["증거개시의 예외","증거개시에서 변호사-고객 특권에 해당하는 법률적 의견이나 소송 준비 과정의 문서 등은 예외적으로 제출이 면제된다"],["약식판결 신청","당사자는 약식판결을 신청할 수 있지만 법원이 이를 반드시 받아들여야 하는 것은 아니며, 복잡한 기술적 쟁점이 있으면 적용이 제한될 수 있다"]]}],"34":[{"t":"table","title":"증거보존","head":["구분","내용"],"rows":[["litigation hold","미국에서는 경고장을 수령하는 순간부터 소송 관련 문서와 이메일 등을 보존해야 하는 의무(litigation hold)가 발생한다"],["위반","보존 의무를 어기고 관련 자료를 고의로 폐기하거나 훼손하면 부정한 행위로 간주되어 소송에서 패소할 수 있다"],["데이터 보존 정책","기업은 문서의 생성·보관·폐기에 관한 데이터 보존 정책을 세우고 변호사-고객 특권을 적절히 활용해 증거개시에 대비해야 한다"]]},{"t":"table","title":"고의침해와 확인의 소","head":["구분","내용"],"rows":[["전문가 의견서","타인의 특허 침해 가능성에 대해 사전에 전문가 의견서를 확보해 두면 고의침해 판단을 피하는 데 도움이 되지만 절대적 수단은 아니다 · 폴라로이드와 코닥의 즉석 카메라 소송에서 코닥은 출시 전에 광범위한 법률 의견을 확보해 고의침해 판정을 피할 수 있었다"],["확인의 소","침해소송이 예견되면 피고는 특허권자가 소송을 내기 전에 비침해 및 무효확인의 소를 제기해 유리한 법원을 선택할 수 있다 · 이미 경고장을 수령한 경우에는 확인의 소가 각하될 수 있으므로 경고장 수령 이전에 신속히 법적 대응을 준비하는 것이 중요하다"]]},{"t":"table","title":"항변과 무효화 절차","head":["구분","내용"],"rows":[["항변","미국 특허소송의 피고는 특허 대상의 적격성, 출원경과 금반언, 선행 무효자료, 권리 행사의 지연(laches), 부정한 방법의 특허 취득 등을 항변으로 검토한다 · 출원경과 금반언의 적용 가능성을 확인하려면 출원 및 심사 과정에서 출원인이나 특허청이 낸 의견을 면밀히 검토해야 한다"],["무효화 행정 절차","미국에서 특허를 무효화하는 행정 절차로는 특허심판항소위원회(PTAB)에서 진행하는 당사자계 재심사(IPR), 등록 후 재심사(PGR), 결정계 재심사 등이 있다 · 재심사 청구가 받아들여지면 법원이 진행 중인 소송을 중지시키는 경우가 많고 신청자의 승소율도 높아 효과적인 전략으로 평가된다"]]}],"35":[{"t":"table","title":"원고의 성격과 소송","head":["구분","내용"],"rows":[["원고의 성격","원고가 제조 기업인지, 비실시기업(NPE)인지, 대학이나 연구소인지에 따라 소송 전략이 달라지므로 원고의 성격과 소송 이력을 파악해야 한다"],["NPE·대학·연구소","NPE나 대학, 연구소가 원고인 경우에는 대부분 침해금지명령보다 라이선스 계약을 통한 수익 창출이 주된 목적이다"],["대리인","미국에서 진행되는 특허침해소송에서는 미국 특허변호사를 주 대리인으로 선임하는 것이 필수적이고 국내 변리사나 변호사를 함께 선임할 수도 있다"],["합의","미국 특허침해소송은 대부분 최종 판결까지 가지 않고 증거개시, 마크만 히어링, 약식판결 단계에서 당사자 합의로 종결된다 · 미국 특허소송 사건의 약 90~95%가 소송 도중 당사자 간 합의로 소가 취하되므로 협상 테이블을 병행하는 것이 바람직하다"]]},{"t":"vs","title":"ITC 소송과 연방지방법원 소송","cols":[{"name":"ITC 소송","items":["Section 337을 위반한 물품의 수입을 금지하기 위한 소송이며, 주된 구제 수단은 손해배상이 아니라 수입금지 조치이다","법률상 12~16개월 내에 종결되어야 하여 훨씬 빠르다","ITC의 결정에 불복하는 당사자는 연방순회항소법원(CAFC)에 항소할 수 있다"]},{"name":"연방지방법원 소송","items":["보통 2~3년이 걸린다"]}]}],"36":[{"t":"table","title":"특허 포트폴리오 관리","head":["구분","내용"],"rows":[["현황 파악","특허 포트폴리오 관리에서 기업이 가장 먼저 할 일은 보유 특허의 종류, 출원 국가, 핵심 기술 등 현황을 정확히 파악하는 것이다"],["가치 평가","특허의 기술적 가치와 시장성을 평가하고 유지 비용과 잠재적 이익을 비교해 특허권을 계속 유지할지 전략적으로 결정한다 · 가치 있는 특허와 그렇지 않은 특허를 구분하는 것은 좋은 아이디어를 출원하는 것보다 어려운 과제여서 기업은 재정적 제약 속에서 선택과 집중을 해야 한다"],["비용","특허의 초기 수수료와 출원 비용은 낮은 편이지만 권리를 유지하는 데 드는 비용은 시간이 지날수록 급격히 증가할 수 있다"],["대리","특허 관련 업무는 권리자가 직접 특허청이나 이해관계인과 처리할 수도 있고 변리사를 통해 대리할 수도 있으며, 업무 복잡성과 시간·비용을 고려해 정한다"]]},{"t":"vs","title":"특허와 상표","cols":[{"name":"특허","items":["특허출원은 신규성 때문에 새로운 국가에서의 출원 시기가 제한된다","기술 혁신의 보호에 중점을 둔다"]},{"name":"상표","items":["타인이 먼저 등록하지 않은 한 언제든 출원해 등록받을 수 있는 유연성이 있다","사용에 의해 권리가 발생하고 유지될 수 있어 제품 출시 이후에도 추가 국가에서 출원이 가능하다는 점에서 특허와 구별된다","브랜드 가치의 보호에 중점을 두어 서로 다른 접근 방식과 타임라인으로 관리해야 한다"]}]},{"t":"table","title":"지식재산 관리와 상용화","head":["구분","내용"],"rows":[["전략적 관리","지식재산 포트폴리오의 전략적 관리에는 등록 가능한 지식재산 목록 작성, 미등록 자산(영업비밀·저작권 등) 확인, 기존 권리의 유지·포기·매각·라이선싱 평가가 포함된다"],["핵심","지식재산 관리의 핵심은 발명의 창출 자체보다 발명을 비즈니스 모델과 연계해 실질적 경제 가치로 전환하는 과정에 있다"],["전문가 팀","기업가, 회계사, 시장조사전문가, 컨설턴트, 엔지니어, 제품디자이너, 은행, 투자자 등 전문가로 팀을 짜면 발명품의 상용화와 시장 진입을 도울 수 있다"],["투자 유치","투자를 유치할 때에는 제품 원형(프로토타입)을 함께 제작해 투자자에게 실현 가능성을 보여 주고 개발 중 문제점을 미리 파악해야 한다"]]}],"37":[{"t":"table","title":"비실시기업(NPE)","head":["구분","내용"],"rows":[["정의","특허발명을 직접 실시하지 않고 특허권을 이용한 소송이나 라이선스로 수익을 얻는 개인 또는 기업을 말한다"],["명칭","특허주장 기업(PAE)이나 라이선스 회사 등으로도 불리며, 중립적 표현인 비실시기업이 부정적 용어인 특허괴물을 대신해 일반화되었다"],["반소·크로스 라이선스","NPE는 제품을 생산하지 않아 다른 기업의 특허를 침해할 가능성이 낮으므로 피고 기업이 반소를 제기하거나 크로스 라이선스를 맺기 어렵다"],["범위","넓은 의미의 NPE에는 대학이나 연구소도 포함될 수 있으나, 이 교재에서는 특허권을 통한 수익 창출을 목적으로 하는 영리 기업만을 NPE로 본다"]]},{"t":"tree","title":"NPE의 유형","root":"NPE의 유형","branches":[["타인의 특허권을 매입하는 유형","가장 전형적인 NPE는 자체 연구개발 없이 타인의 특허권을 매입해 라이선싱과 소송으로 수익을 올리는 유형으로 전체 NPE의 약 80%를 차지한다"],["독자 연구개발 유형","독자 연구개발로 특허를 확보하는 유형"],["독자 개발과 매입 병행 유형","독자 개발과 특허 매입을 병행하며 자체 특허 개발 부서를 둔 유형"],["제조업체 출신","원래 제조업체였다가 파산이나 사업 정리 후 남은 특허권으로 수익을 올리는 기업도 NPE의 한 유형이다"]]},{"t":"table","title":"NPE 소송 통계","head":["연도","내용"],"rows":[["2022년","미국에서 한국 기업을 상대로 한 특허소송 109건 중 NPE가 제기한 것은 76건으로 69.7%에 이르러 최근 5년 중 가장 높았다"],["2023년","미국 지방법원 특허소송 3,108건 중 텍사스 동부는 613건, 텍사스 서부는 519건이며, 이 지역 소송의 약 85~90%가 NPE에 의해 제기되었다"]]}],"38":[{"t":"table","title":"NPE 서면 회신","head":["구분","내용"],"rows":[["NPE 분쟁","NPE와의 특허침해 분쟁은 절차는 일반 특허침해소송과 같지만 NPE의 특수성을 고려한 맞춤형 대응 전략을 세워야 하며, 미국이 NPE 활동이 가장 활발한 곳이다"],["회신 방식","NPE가 보낸 라이선스 요구 서면에는 타인의 특허권을 존중하는 태도를 보이면서 침해 제품 특정과 구성 대 구성 비교 등 상세한 설명을 요구하는 방식으로 회신하는 것이 바람직하다 · 침해 부분의 구성 대 구성 비교를 담은 클레임 차트와 라이선스 조건 제시를 요청하며 전문적으로 대응하는 것이 좋다"],["협상 시 주의","미국에서는 NPE와의 협상 과정에서 오간 논의 내용이 증거개시 절차의 대상이 될 수 있으므로 협상 시 정보 공유에 신중해야 한다"],["합의","NPE와의 합의가 유리하다고 판단되면 라이선스 계약이나 부제소특약(Covenant Not to Sue)을 체결해 분쟁을 끝낼 수 있다"],["증거보존 통지","미국 소송에 대비해 관련 있다고 판단되는 사내 인원 모두에게 증거보존 통지(litigation hold) 명령을 내려야 한다"]]},{"t":"table","title":"NPE 맞춤형 대응","head":["구분","내용"],"rows":[["NPE 조사","경고장을 보낸 NPE의 성격, 과거 소송 이력, 보유 특허 규모, 재정 능력, 라이선스 체결 현황을 조사하면 맞춤형 대응 전략을 세울 수 있다"],["요구 수준","소액 합의를 선호하는 NPE에는 신속한 협상 전략이 효과적이고, 고액 로열티를 요구하는 NPE에는 더 강력한 법적 대응이 필요할 수 있다"],["특허의 강도","여러 차례의 소송에서 유효성이 인정된 특허는 비교적 강력한 특허로 보고, 소송이나 재심사 경험이 없는 특허는 무효 가능성이 상대적으로 높을 수 있다"],["첫 라이선스","아직 라이선스가 없는 특허라면 첫 라이선스 계약이 되므로 상대적으로 낮은 로열티율로 분쟁을 해결할 가능성이 높다"]]}],"39":[{"t":"table","title":"NPE 소송 전략","head":["구분","내용"],"rows":[["법원","NPE는 주로 원고 승소율이 높고 진행이 빠른 법원을 선호하고, 피고는 진행이 느리고 원고 승소율이 낮은 법원을 선호한다 · NPE가 소송을 제기한 법원이 불리하다고 판단되면 이송신청(venue transfer motion)을 고려할 수 있으나 해당 법원의 재량에 달려 있다"],["공동 대응","NPE가 100개가 넘는 회사를 상대로 소송을 내는 경우에는 같은 피고들이 소송 비용을 분담하고 공동 대응하는 것이 전략적으로 유리할 수 있다 · 공동 대응을 위해서는 참여 기업 간 역할 분담, 비용 분담 원칙, 정보 공유 범위에 대한 사전 합의가 필요하다"],["반소","NPE는 특허발명을 직접 실시하지 않아 반소를 제기하기 어렵지만, 경우에 따라 특허권 남용, 반독점법 위반, FRAND 조건 위반 등을 근거로 한 반소를 검토할 수 있다"],["마크만 히어링","어느 한 당사자의 신청으로 시작되며 소송 초기에 진행되면 주로 피고에게 유리한 경향이 있다 · 초기에 청구범위를 확정하면 증거개시 비용을 크게 줄일 수 있는데, NPE는 제출할 증거가 적어 비용 부담이 상대적으로 적다"],["배심재판","NPE 소송은 대부분 배심재판이므로 NPE가 혁신과 산업 발전에 기여하는 바가 없다는 점을 배심원단에게 설득하는 것이 효과적인 전략이 될 수 있다"]]}],"40":[{"t":"table","title":"IPR·PGR·CBM 비교","head":["항목","IPR","PGR","CBM"],"rows":[["신청 시기","특허등록 후 9개월 이후 또는 PGR 종료 후","특허등록 후 9개월 이내","BM 특허 관련 소송의 당사자 또는 위협받은 자가 신청"],["무효 사유","신규성과 진보성 결여","모든 무효 사유를 주장할 수 있다","비즈니스 방법 관련 특허를 대상으로 하며 2020년 9월 15일에 종료되었다"],["신청 자격","특허권자를 제외한 누구나 신청할 수 있다","특허권자를 제외한 누구나 신청할 수 있다","BM 특허 관련 소송의 당사자 또는 위협받은 자"],["기준","청구항이 무효일 합리적 가능성","청구항 무효 가능성이 더 높음","IPR, PGR, CBM은 모두 신청이 수락된 후 1년 안에 진행되며 6개월의 연장이 가능하다"],["대상 특허","모든 특허","미국 개정 특허법(AIA) 하에서 등록된 특허","비즈니스 방법 관련 특허"]]},{"t":"def","term":"IPR 이용 시 주의","text":"IPR은 특허 유효성을 다투는 효과적 수단이지만 피고가 먼저 비침해·무효확인소송을 제기하면 이용할 수 없어 전략 선택에 주의가 필요하다"}],"41":[{"t":"table","title":"NPE 특허의 방어","head":["구분","내용"],"rows":[["무효화 가능성","NPE 특허의 무효화 가능성을 높이기 위해 발명자 조사, 심사이력 분석, 선행기술 조사, 공지기술 증거 수집 등을 활용할 수 있다"],["출원경과 금반언","특허권 취득 과정에서 특허권자가 취한 조치나 제시한 의견과 모순되는 주장을 후속 소송에서 하지 못하도록 제한하는 원칙이다 · IPR을 거친 특허는 재심 과정에서 특허권자나 청구인이 제시한 의견도 금반언의 대상이 되어 소송에서 이와 모순되는 주장을 할 수 없다"],["부정한 행위","출원 과정에서 중요한 정보를 고의로 누락하거나 허위 정보를 제공한 부정한 행위가 있었다면 특허권 행사가 제한될 수 있다"]]}],"42":[{"t":"table","title":"ADR","head":["구분","내용"],"rows":[["ADR","재판 외 분쟁해결(ADR)은 재판을 대신해 분쟁을 처리하는 제도로, 중재, 조정, 화해 등이 대표적이다"],["지식재산 기본법","우리나라는 2011년 지식재산 기본법을 제정해 ADR의 활성화와 전문성 제고, 국민들의 쉬운 이용을 위한 안내와 홍보 강화를 규정하고 있다"]]},{"t":"vs","title":"ADR의 장점","cols":[{"name":"민사소송","items":["민사소송법에 규정된 엄격한 절차","승패를 가르는 일도양단식 방식","법원의 재판은 공개주의 원칙을 따른다"]},{"name":"ADR","items":["당사자의 합의에 따라 형식과 격식을 완화해 진행할 수 있다","양 당사자가 윈-윈할 해결책을 모색할 수 있어 지속적인 비즈니스 관계를 유지하는 데 유리하다","대부분 비공개로 진행되어 영업비밀과 기업 평판을 보호하기에 유리하다","해당 분야의 전문가들이 참여해 복잡한 기술 관련 분쟁에서 더 유연하고 정확한 결과를 도출할 가능성이 높다","당사자들의 자발적 의사에 따라 진행되므로 분쟁해결 과정에 대한 만족도가 높고 결과 수용도도 높은 편이다"]}]}],"43":[{"t":"table","title":"ADR의 단점과 알선","head":["구분","내용"],"rows":[["절차 보장","충분한 절차보장과 사실관계 조사가 없으면 경제적·사회적 강자에게 유리한 결과가 나올 위험이 있다"],["불복","ADR에서 한 당사자가 결과에 불복하면 오히려 소송보다 더 많은 시간과 비용이 들 수 있다"],["중재","중재는 불복 절차가 없어 잘못된 판단이 내려지면 돌이킬 수 없다는 점이 단점이다"],["알선 및 주선","중립적인 제3자가 양 당사자의 교섭을 중재해 합의를 유도하는 방법으로, 특별한 자격이나 권한 없이도 누구나 수행할 수 있다"]]}],"44":[{"t":"vs","title":"조정과 화해","cols":[{"name":"조정","items":["제3자(법관 또는 조정위원회)가 독자적으로 타협 방안을 마련해 당사자의 수락을 권고하는 제도이다","중재와 달리 권고안에 강제력이 없고, 화해와 달리 제3자가 개입한다는 특징이 있다","우리나라는 조정을 규율하기 위해 민사조정법을 제정해 시행하고 있다","법원이 관여하는 민사조정에서 조정이 성립되어 조정조서가 작성되면 확정판결과 동일한 효력을 갖는다"]},{"name":"협상 및 화해","items":["제3자의 개입 없이 양 당사자가 직접 교섭하여 상호 양보를 통해 분쟁을 해결하는 방식이다"]}]}],"45":[{"t":"table","title":"산업재산권 분쟁조정","head":["구분","내용"],"rows":[["조정 기관","지식재산권 분야에서는 특허청 산하 산업재산권분쟁조정위원회, 한국저작권위원회의 조정부, 법원조정센터 등이 조정을 수행한다"],["조정조서","산업재산권 분쟁조정에서 조정조서가 작성되면 재판상 화해로 인정되어 확정판결과 동일한 효력을 갖는다"],["조정 불성립","피신청인이 답변서를 내지 않거나 조정에 응하지 않으면 조정이 성립하지 않고 종료되며, 화해권고를 수락하지 않을 때에도 마찬가지이다"]]},{"t":"flow","title":"산업재산권 분쟁조정 절차","steps":["조정신청서 접수","출석요청서 발송","답변서 접수","조정부 구성","조정의회 개최(화해권고)","조정조서 작성"]}],"46":[{"t":"vs","title":"심판과 소송","cols":[{"name":"심판","items":["특허심판원 같은 행정기관에서 주로 진행되어 소송보다 신속하고 비용 부담이 적지만 법적 구속력은 상대적으로 약하다"]},{"name":"소송","items":["특허법원 같은 사법기관에서 이루어지고 강력한 구속력을 가지지만 시간과 비용이 많이 들며, 패소하면 막대한 법적 비용을 감당해야 한다"]}]},{"t":"table","title":"분쟁 절차의 구분","head":["구분","내용"],"rows":[["행정부","특허 분쟁 절차는 행정부인 특허심판원에서 진행하는 절차와 사법부(일반법원·고등법원·특허법원·대법원)에서 진행하는 절차로 나뉜다 · 특허취소신청, 특허무효심판, 권리범위확인심판은 특허심판원에서 진행한다"],["사법부","가처분신청과 침해금지·손해배상청구소송은 사법부에서 진행한다 · 가처분과 침해금지청구소송의 쟁점은 무효심판과 권리범위확인심판의 쟁점과 거의 같아 심판 경험이 풍부한 변리사를 선임하는 것이 필수적이다"],["대리인 선임","변리사와 변호사는 동시에 이해가 상충되는 사건을 대리할 수 없으므로, 분쟁이 예상되면 상대편이 위임하기 전에 대리인을 먼저 선임하는 것도 중요하다"],["분쟁 예방과 해결","분쟁 예방을 위해 출원 전 선행기술 조사로 특허의 유효성을 확보하고, 제품 제조 시 사전 FTO 검토로 타사 특허의 침해를 피하며, 라이선스 계약의 권리·의무를 명확히 한다 · 분쟁이 발생하면 소송은 최후의 수단으로 두고 가급적 조정이나 화해를 먼저 모색하는 것이 바람직하다"]]},{"t":"table","title":"특허 분쟁 사례","head":["사례","내용"],"rows":[["애플과 삼성","특허 분쟁은 2011년 애플이 삼성을 상대로 디자인 및 기술 특허 침해 소송을 제기하면서 시작되어 여러 국가에서 수십 건의 소송으로 이어졌다"],["구글과 오라클","자바 API 소송에서 2021년 미국 대법원은 구글의 자바 API 사용이 공정 사용 원칙에 부합한다고 최종 판결했다"],["퀄컴과 애플","2017년 애플이 퀄컴의 로열티 부과를 반독점 행위라며 소송을 낸 것으로 시작되어 2019년 전격적인 화해로 끝났다 · 애플은 퀄컴에 일정액의 화해금을 지급하는 대신 6년간 퀄컴의 칩셋 공급과 라이선스 계약을 보장받았다"]]}],"47":[{"t":"table","title":"가처분","head":["구분","내용"],"rows":[["가처분","본안 소송이 확정되기 전까지 긴급한 권리 보호를 위해 허용되는 잠정 조치로, 법원이 양측의 이해관계와 본안 승패 예상 등을 고려해 재량으로 허가 여부를 정한다"],["만족적 가처분","특허권 침해 금지나 예방을 명하는 만족적 가처분은 보전의 필요성 판단에 더욱 신중을 기한다"],["상대방의 대응","가처분 신청을 받은 상대방은 주로 특허무효심판을 제기하는데, 특허가 무효로 확정되면 처음부터 존재하지 않았던 것으로 간주되어 분쟁 종결에 유리하기 때문이다"],["손해배상청구","특허 침해는 불법행위에 해당하므로 특허권자는 손해배상청구소송을 통해 손실에 대한 금전적 보상을 받을 수 있다"],["가처분이 인용된 후","특허가 무효심판으로 무효가 되거나 침해소송에서 비침해 판단을 받으면, 피청구인은 특허권자에게 손해배상을 청구할 수 있다"]]},{"t":"table","title":"가처분 신청서","head":["구분","내용"],"rows":[["제출 법원","가처분 신청서는 본안 소송이 진행 중이면 해당 법원에 내고, 진행 중이 아니면 앞으로 본안이 제기될 때 이를 관할할 법원에 제출한다"],["기재 사항","가처분 채권자, 가처분 채무자, 침해 대상 제품, 신청 취지, 신청 이유를 작성해 제출한다"],["신청 취지","채무자의 제품 생산·사용·판매·배포 금지, 제품과 반제품의 점유를 풀어 집행관에게 인도할 것, 집행관이 보관 취지를 공시할 것 등을 쓴다"],["신청 이유","특허권 침해가 이미 발생했거나 발생할 예정임을 특허발명과 침해 대상 제품을 비교해 설명하고 본안 확정을 기다리면 심각한 피해가 생김을 소명해야 한다"],["담보","법원은 일정한 담보금을 공탁하는 조건으로 가처분 명령을 내릴 수 있어, 신청인은 공탁금을 납부하거나 보증보험에 가입해 대비해야 한다"]]},{"t":"table","title":"손해배상 청구 소장","head":["구분","내용"],"rows":[["청구 취지","손해배상 청구 소송의 소장에는 당사자의 명칭과 주소, 청구 취지, 청구 원인을 작성하며 청구 취지는 피고가 원고에게 지급할 금액으로 구체적으로 쓴다"],["청구 원인","침해로 인한 매출 감소, 시장 점유율 하락 같은 손해 발생 사실과 그 규모, 손해액 산정 근거를 입증 자료와 함께 제시해야 한다"]]}],"48":[{"t":"table","title":"이해관계인","head":["구분","내용"],"rows":[["이해관계인","특허 분쟁의 이해관계인은 특허권의 귀속이나 행사에 직접적 또는 간접적인 이해관계를 가진 자로, 특허권자·전용실시권자·통상실시권자·잠재적 실시권자 등을 포함한다"],["심판 필요","특허침해로 경고를 받을 가능성이 있는 사람은 특허무효심판으로 해당 특허를 무효화하거나 권리범위확인심판으로 비침해를 확인할 필요가 있다"],["이해관계가 없는 경우","이해관계가 없는 사람이 심판을 청구하면 당사자 적격의 흠결로 부적법하다고 판단되어 각하된다"],["청구인적격","특허법상 무효심판 청구인적격은 이해관계인으로 한정되어 있어, 청구인은 직접적이고 구체적인 이해관계가 있음을 증명해야 청구가 적법하다"]]},{"t":"tree","title":"무효심판에서 이해관계가 인정되는 예","root":"무효심판의 이해관계인","branches":[["소추를 받은 자 등","해당 특허권의 소추를 받은 자, 특허발명의 실시준비를 하는 자, 동종의 물건을 제조하는 자"],["선사용 통상실시권자 등","선사용에 의한 통상실시권을 가진 자와 해당 특허발명과 동일할 염려가 있는 발명을 실시하는 자"],["동종 업종 종사자","같은 업종에 종사하고 있음을 사업자등록증으로 증명하면 특별한 사정이 없는 한 무효심판에서 이해관계가 인정된다"]]},{"t":"table","title":"권리범위확인심판과 참가","head":["구분","내용"],"rows":[["소극적 권리범위확인심판","확인대상발명을 실시하고 있는 자 또는 장래에 실시할 예정이 있는 자가 이해관계인이다"],["특허심판원","사업자등록증으로 동종 업계 종사를 입증하면, 신약 개발 중인 제약회사처럼 아직 실시하지 않는 자의 권리범위확인심판 청구인적격도 인정한다"],["2014당3070 사건","심판부는 의약품 제조업자가 장래 실시할 가능성이 있는 발명을 확인대상발명으로 특정해 청구한 심판청구에 확인의 이익이 있다고 보았다"],["참가","특허심판이 진행 중일 때 제3자가 자기의 법률적 이익을 보호하기 위해 심판 당사자 중 한쪽에 참여하는 것으로, 당사자참가와 보조참가가 있다"],["당사자참가","무효심판이나 소극적 권리범위확인심판을 청구할 자격이 있는 자가 심판청구인 측에 참여하는 것이다"]]}],"49":[{"t":"table","title":"심판청구서","head":["구분","내용"],"rows":[["기재 사항","심판청구서에는 당사자의 성명 및 주소, 대리인의 성명 및 주소 또는 영업소 소재지, 심판사건의 표시, 청구의 취지 및 이유를 기재해야 한다"],["특허무효심판의 청구취지","특허 제00호(또는 그 청구항 제00항)를 무효로 한다는 내용과 심판비용을 피청구인이 부담한다는 내용으로 쓸 수 있다"],["존속기간연장등록무효심판","특허 제00호의 존속기간연장등록을 무효로 한다는 취지로 청구한다"],["소극적 권리범위확인심판","청구취지는 확인대상발명이 특허 제00호의 권리범위에 속하지 아니한다는 내용이다"],["무효심판의 청구 이유","신규성 결여, 발명의 설명이 명확하지 않은 미완성 발명, 진보성 결여 등 구체적인 무효사유를 사실관계와 함께 적어야 한다 · 신규성 결여를 이유로 무효심판을 청구하는 예시에서는 출원일 전에 공고된 선행특허의 구성이 청구항의 구성과 동일하거나 실질적으로 동일함을 근거로 든다"]]},{"t":"flow","title":"외국어 증거자료","steps":["청구 이유를 뒷받침하는 증거자료가 외국어인 경우에는 한글 번역문을 함께 제출하는 것이 원칙이다","번역문이 제출되지 않으면 심판장이 기간을 정해 보정명령을 내릴 수 있다","그래도 제출하지 않으면 해당 증거자료는 제출되지 않은 것으로 간주될 수 있다"]},{"t":"table","title":"확인대상발명","head":["구분","내용"],"rows":[["첨부","권리범위확인심판을 청구할 때에는 확인대상발명에 관한 설명서와 필요한 도면을 청구서에 함께 첨부해야 한다"],["특정","확인대상발명은 특허발명의 구성요소와 비교해 차이점을 판단할 수 있을 정도로 구체적으로 특정되어야 하지만 대상물의 전체 구성을 모두 적을 필요는 없다"],["기능적 표현","확인대상발명이 기능적 표현으로만 기재되어 통상의 기술자가 기술적 의미를 명확히 파악할 수 없다면 구체적으로 기재된 것으로 보지 않아 청구가 각하될 수 있다"],["불명확한 구성요소","확인대상발명의 설명서에 일부 구성요소가 불명확하더라도 나머지 구성요소만으로 권리범위에 속하는지 판단할 수 있다면 확인대상발명은 특정된 것으로 간주된다"]]}],"50":[{"t":"vs","title":"방식심리와 적법성 심리","cols":[{"name":"방식심리","items":["심판청구 절차에 필요한 서류가 제대로 제출되었는지와 기재 방식·수수료 납부가 정상적인지를 확인하는 절차이다","심판청구서의 형식적 요건을 검토하는 절차이다","권리범위확인심판을 청구할 때는 특허발명과 비교할 수 있는 설명서와 필요한 도면을 심판청구서와 함께 제출해야 한다"]},{"name":"적법성 심리","items":["심판청구가 법적으로 적합한지를 판단하는 과정이다","심판합의체가 심판청구의 적법 여부를 판단하는 과정이다","실존하지 않는 자를 당사자로 하는 심판청구는 부적법한 청구로 본다","이해관계가 없는 자가 한 심판청구는 당사자적격이 없어 부적법하다"]}]},{"t":"table","title":"반려와 보정","head":["구분","내용"],"rows":[["서류 반려","서류 반려 이유 통지를 받은 심판청구인은 서류의 하자를 수정할 수 없고 소명 기간 내에 소명서만 제출할 수 있다 · 소명 내용이 이유 없다고 인정되어 심판서류가 반려된 경우 심판청구인은 행정심판이나 행정법원에 불복할 수 있다"],["보정명령 사유","미성년자 같은 행위 무능력자가 청구인으로 기재되었거나 절차 관련 수수료를 내지 않은 경우는 보정명령 사유에 해당한다"],["보정의 범위","심판청구서와 부속서류의 보정은 그 요지를 변경하지 않는 범위 안에서만 가능하다"],["보정 미이행","보정으로 하자를 치유하지 않으면 심판 절차가 무효가 되거나 결정으로 청구서가 각하될 수 있다 · 보정 미이행으로 절차가 무효가 된 경우에는 행정심판이나 행정법원에, 결정으로 청구서가 각하된 경우에는 특허법원에 불복할 수 있다"]]}],"51":[{"t":"table","title":"심리병합","head":["구분","내용"],"rows":[["의미","둘 이상의 심판사건을 하나의 절차로 합쳐서 심리하는 것으로, 특허법에 근거를 두고 있다"],["목적","심리병합의 주된 목적은 중복 심리를 피하고 절차의 경제성을 높이며 심결 간의 모순을 방지하는 것이다"],["요건","당사자 쌍방 또는 일방이 동일하고 둘 이상의 심판이 동일한 종류이며 심리가 종결되기 전일 때 가능하다"],["결정","심리병합 여부는 심판관(합의체)이 직권으로 결정하고, 병합하는 경우 심판장이 그 취지를 당사자에게 통지한다"],["효과","심리를 병합한 심판사건은 동시에 동일한 심결문으로 각 사건을 심결하는 것이 가능하다 · 심리가 병합되면 병합 전 각 사건에서 제출된 서류와 증거방법은 병합된 다른 사건에서도 이용될 수 있다"],["증거방법 채택","병합 전 증거방법을 채택할 때에는 당사자에게 의견서나 답변서를 제출할 기회를 반드시 주어야 한다"]]},{"t":"tree","title":"우선심판","root":"우선심판은 심리를 청구일 순서대로 진행하는 일반 원칙에서 벗어나 다른 사건보다 먼저 심판하는 것이다","branches":[["유형","당사자의 신청에 의한 것과 심판 기관의 직권에 의한 것 두 가지 유형이 있다"],["직권에 의한 우선심판","심결취소소송에서 취소된 사건이나 심사관이 직권으로 무효심판을 청구한 사건"],["신청 사유","국민경제상 긴급한 처리가 필요한 사건이나 군수품 등 전쟁수행에 필요한 심판사건"],["결정","우선심판 청구가 접수되면 심판장은 심판정책과로부터 청구서를 인계받은 날부터 15일 이내에 우선심판 대상 여부를 결정해 당사자에게 통보한다"]]}],"52":[{"t":"table","title":"증거능력과 증거력","head":["구분","내용"],"rows":[["증거능력","증거조사의 대상이 될 자격을 말한다"],["증거력","증거자료가 사실 인정을 얼마나 잘 증명하는지를 말한다"],["형식적 증거력","문서 증거에서 중요하며 특정인의 의사에 의해 작성된 진정성립이 있는지를 판단하는 것이다 · 공문서는 형식적 증거력에 특별한 문제가 없고, 사문서는 위변조가 명확하지 않으면 형식적 증거력이 인정된다"],["실질적 증거력","형식적 증거력이 인정된 경우에만 실질적 증거력을 판단하며, 실질적 증거력은 심판관의 자유로운 판단에 맡겨진다"]]},{"t":"flow","title":"증거조사와 증인신문","steps":["증거조사는 일반적으로 증거 신청, 채택 여부 결정, 증거조사 실시, 실시 결과의 순서로 진행된다","증인신문은 가능한 한 구술심리에서 진행하며, 신청서에는 증인신문이 필요한 이유, 증인의 인적사항, 증인신문사항을 기재해야 한다","증인신문 절차는 신청, 신문 결정, 비용 예납, 신문 실시의 순서로 진행된다","상대방 당사자는 증인신문사항을 받은 후 반대신문을 할 수 있으며, 반대신문사항을 미리 작성해 반대신문 직전까지 심판장에게 제출해야 한다"]},{"t":"table","title":"감정과 심리 방식","head":["구분","내용"],"rows":[["감정","특별한 학식과 경험을 가진 전문가에게 그 지식과 판단을 보고하게 하여 심판관의 판단 능력을 보완하는 증거조사이다 · 감정이 완료되면 심판부는 감정조서를 작성하며, 이 조서는 증인신문 절차에 준하여 활용된다"],["구술심리·서면심리","심판은 구술심리 또는 서면심리로 진행할 수 있으며 어느 방식을 쓸지는 심판장이 판단하되, 당사자가 구술심리를 신청하면 특별한 사정이 없는 한 구술심리를 개최한다"],["서면심리의 장점","서면심리는 제출된 서류를 바탕으로 판단하므로 구술심리보다 시간과 비용이 절약되며, 사건이 단순하고 쟁점이 명확할 때 유용하다"]]}],"53":[{"t":"vs","title":"강제 해결과 합의 해결","cols":[{"name":"심판과 소송","items":["상대방 의사와 관계없이 국가 권력으로 강제 해결하는 방식이다","하나의 제품에 대해 무효심판, 권리범위확인심판, 침해금지가처분 등이 제기되면 각 사건이 1심부터 3심까지 진행되어 재판 건수가 수십 건에 이를 수 있다"]},{"name":"화해·조정·중재","items":["당사자 쌍방의 합의로 해결하는 방식이다","화해는 분쟁을 자주적으로 해결하는 방식으로, 재판 과정에서 이루어지는 화해와 재판 외에서 이루어지는 화해 두 가지가 있다"]}]},{"t":"vs","title":"침해에 대한 구제","cols":[{"name":"민사적 구제","items":["침해금지청구","손해배상청구"]},{"name":"형사적 구제","items":["고소·고발","수사 의뢰"]}]}],"54":[{"t":"table","title":"심판 단계의 화해","head":["구분","내용"],"rows":[["심판 단계","특허 심판에서는 재판 외 화해로 심판청구를 취하할 수는 있지만, 심판부 앞에서 화해조서를 작성할 수는 없다"],["재판상 화해 규정이 없는 이유","특허 무효 심결은 당사자뿐 아니라 모두에게 영향을 미치므로 이를 당사자 사이에서 무효 또는 유효로 바꾸는 것이 바람직하지 않아 심판 단계의 재판상 화해 규정이 없다"],["취하 후","당사자의 화해로 무효심판이 취하되더라도 심판원의 판단에 따라 심사관이 무효심판의 청구인이 되어 현출된 증거로 다시 심판을 진행할 수 있다"],["소송 단계","특허권 침해금지 청구나 손해배상 청구 소송은 당사자 사이의 법적 관계를 규율하는 것이므로 화해의 대상이 될 수 있다"],["화해 조건","특허 분쟁의 화해 조건으로는 무효심판 청구를 취하하고 권리자가 권리행사를 하지 않는 방식, 여기에 로열티를 지급하는 방식 등이 있다 · 추후 다시 심판청구를 하지 않겠다는 부제소 협약이나 비밀 준수 의무가 포함될 수 있다"]]}],"55":[{"t":"vs","title":"조정과 중재","cols":[{"name":"조정","items":["법관이나 조정위원회가 분쟁 당사자들 사이에 개입하여 화해를 이끌어내는 절차이다","조정이 성립되어 조정조서가 작성되면 재판상 화해와 같은 효력을 가지며, 그 효력을 다투려면 준재심 절차를 통해서만 가능하다"]},{"name":"중재","items":["당사자들이 합의하여 선택한 중재인이 중재판정을 내려 분쟁을 해결하는 절차로, 본질은 사적인 재판이라는 점에 있다","단심제로 이루어져 소송보다 신속하고 비용이 저렴하며, 분야 전문가를 중재인으로 선정할 수 있고 비공개로 진행되어 비밀 유지에도 유리하다","중재를 신청하려면 분쟁을 중재로 해결하기로 하는 당사자 간의 중재 합의가 있어야 하며, 합의가 없으면 중재 신청은 불가능하다","특허 분쟁에 관한 중재는 주로 대한상사중재원의 지식재산권분쟁조정중재를 통해 이루어진다"]}]}],"56":[{"t":"table","title":"특허심판의 구분","head":["구분","내용"],"rows":[["특허심판","산업재산권의 발생·변경·소멸 및 권리범위에 관한 분쟁을 해결하기 위한 특별한 행정심판이다"],["결정계 심판","심사관의 처분에 불복하는 사람이 청구하는 것으로 대립하는 상대방이 없다 · 결정계 심판에는 거절결정불복심판과 정정심판이 있다"],["당사자계 심판","당사자들이 서로 대립하는 구조이다 · 특허무효심판, 존속기간 연장등록 무효심판, 정정무효심판, 권리범위확인심판, 통상실시권 허락의 심판이 있다"]]},{"t":"table","title":"거절결정불복심판","head":["구분","내용"],"rows":[["청구기간","특허 거절결정을 받은 사람이 불복할 때는 결정 등본을 받은 날부터 3개월 이내에 심판을 청구할 수 있다"],["대상","특허 거절결정뿐 아니라 특허권의 존속기간 연장등록 거절결정에 불복하는 경우에도 청구할 수 있다"],["승소","청구인이 승소하면 이전의 거절결정이 취소되고 심사가 다시 진행될 수 있다"],["분할출원","출원인은 거절결정불복심판의 결과가 부정적일 수 있으므로 심판과 동시에 별도의 분할출원을 해 두어 추가 대응 기회를 가질 수 있다"],["분리출원","2022년 도입된 분리출원 제도에 따라 거절결정불복심판에서 청구항 세트 전체가 계류되어 부정적 결과를 얻더라도, 등록 가능하다고 판단받은 청구항 세트는 분리출원으로 다시 등록을 도모할 수 있다"]]},{"t":"tree","title":"정정심판","root":"정정심판은 특허발명의 동일성을 유지하는 범위 안에서 명세서나 도면의 정정을 요구하는 심판이다","branches":[["정정 범위","소급 효과로 인한 제3자의 예기치 못한 피해를 방지하기 위해 정정 범위에 제한을 둔다"],["청구 요건","특허발명의 무효 사유를 해결할 수 있는 실질적인 이익이 있을 때 청구할 수 있다"]]}],"57":[{"t":"table","title":"특허취소신청","head":["구분","내용"],"rows":[["신청","특허취소신청제도에서는 누구든지 특허 등록공고 후 6개월까지 특허취소 사유를 제기할 수 있고, 심판합의체가 취소 여부를 결정한다"],["대상","특허법 제29조나 제36조의 취소 사유에 해당하는 특허에 대해 할 수 있으며, 제29조 제1항 제1호와 쉽게 발명할 수 있는 경우는 제외된다"],["성격","정보 제공 제도의 연장선에서 하자가 있는 특허를 조기에 시정하기 위한 제도이며, 취소신청인이 승소하면 특허권은 소급적으로 소멸된다"],["무효심판과의 차이","취소신청은 무효심판에 비해 명확한 사유에 대해 등록결정 이후 신속하게 결정할 수 있고, 이해관계인이 아닌 제3자도 신청할 수 있다"]]}],"58":[{"t":"table","title":"무효심판","head":["구분","내용"],"rows":[["청구","이해관계인이나 심사관은 특허가 특허법상 무효 사유에 해당하는 경우 무효심판을 청구할 수 있다"],["승소","청구인이 승소하면 특허권은 원칙적으로 처음부터 없었던 것처럼 소급하여 소멸하며, 후발적 무효 사유는 예외이다"],["의미","특허 침해 경고를 받은 사람이 특허 자체를 무효화함으로써 분쟁을 근본적으로 해결할 수 있는 수단이 된다"]]},{"t":"table","title":"존속기간 연장등록 무효와 정정 무효","head":["구분","내용"],"rows":[["존속기간 연장등록 무효심판","특허권의 존속기간 연장등록에 무효 사유가 있을 때 이해관계인이나 심사관이 무효심판을 청구할 수 있다 · 무효로 하는 심결이 확정되면 그 연장은 처음부터 없었던 것으로 간주되나, 연장 가능 기간을 초과한 경우에는 초과된 기간만 소멸된다"],["정정 무효심판","정정이 정정 관련 규정을 위반한 경우 이해관계인이나 심사관은 정정 무효심판을 청구할 수 있으며, 무효가 확정되면 정정은 처음부터 없었던 것으로 간주된다 · 정정을 통해 특허권의 보호범위가 부당하게 확장·변경되어 제3자가 예상치 못한 손해를 입는 것을 방지하기 위한 제도이다"]]}],"59":[{"t":"vs","title":"권리범위확인심판","cols":[{"name":"적극적 권리범위확인심판","items":["청구인이 승소하면 제3자의 발명이 특허발명의 권리범위에 속하는 것으로 판단될 수 있다"]},{"name":"소극적 권리범위확인심판","items":["청구인이 승소하면 제3자의 발명이 특허발명의 권리범위에 속하지 않아 자유롭게 실시할 수 있는 것으로 판단된다"]}]},{"t":"table","title":"권리범위확인과 실시허락","head":["구분","내용"],"rows":[["권리범위확인심판의 역할","권리범위를 공적으로 확인받아 분쟁을 조기에 해결하고 소송으로 이어지는 것을 방지하는 역할을 한다"],["통상실시권 허락의 심판","특허권자, 전용실시권자 또는 통상실시권자는 상대방이 정당한 이유 없이 실시 허락을 거부하면 청구할 수 있다 · 청구인이 승소하면 강제실시권을 취득할 수 있다"],["취지","선원권리자의 이익을 부당하게 해치지 않으면서 후원권리자가 자신의 발명을 실시할 수 있게 하여 산업 발전에 기여하려는 제도이다"]]}],"60":[{"t":"table","title":"디자인 심판의 종류","head":["구분","내용"],"rows":[["디자인보호법상 심판","보정각하결정 불복심판, 거절결정 불복심판, 취소결정 불복심판, 디자인등록무효심판, 권리범위확인심판, 통상실시권 허락의 심판이 있다"],["없는 심판","디자인보호법에는 존속기간연장등록 거절결정 불복심판과 존속기간연장등록 무효심판이 없다 · 등록 후 권리 내용을 정정하는 정정심판과 정정무효심판이 없다"],["디자인보호법에만 있는 심판","보정각하결정 불복심판과 일부심사등록 이의신청의 취소결정에 대한 불복심판은 특허법에는 없고 디자인보호법에만 있는 심판이다"]]},{"t":"table","title":"디자인 불복심판","head":["심판","내용"],"rows":[["보정각하결정 불복심판","보정이 요지변경이라는 이유로 보정각하 결정을 받은 사람이 불복하려면 결정 등본을 받은 날부터 3개월 이내에 심판을 청구할 수 있다 · 청구인이 승소하면 보정각하 결정이 취소되고 보정이 적법하게 인정된 상태로 심사가 다시 진행될 수 있다"],["취소결정 불복심판","디자인등록 취소 결정을 받은 사람은 결정 등본을 받은 날부터 3개월 이내에 불복심판을 청구할 수 있고, 승소하면 취소 결정이 취소되어 심사가 다시 진행된다"],["거절결정 불복심판","디자인등록 거절 결정을 받은 사람은 결정 등본을 받은 날부터 3개월 이내에 불복심판을 청구할 수 있고, 승소하면 거절 결정이 취소되어 심사가 다시 진행된다"]]}],"61":[{"t":"table","title":"디자인 무효·확인·허락","head":["심판","내용"],"rows":[["디자인등록 무효심판","디자인등록에 무효 사유가 있으면 하자 있는 등록을 소급하여 소멸시키기 위해 무효심판을 청구하며, 후발적 무효 사유는 제외된다"],["권리범위확인심판","확인대상디자인이 등록디자인의 보호범위에 속하는지 여부를 확인하는 심판이다 · 소극적 권리범위확인심판에서 청구인이 승소하면 제3자의 디자인은 디자인권의 권리범위에 속하지 않는 것으로 판단되어 자유롭게 사용할 수 있게 된다"],["통상실시권 허락의 심판","디자인권자·전용실시권자·통상실시권자는 이용·저촉 관계에서 선권리자가 정당한 이유 없이 실시를 허락하지 않으면 청구할 수 있다 · 청구인이 승소하면 강제실시권을 취득할 수 있다"]]}],"62":[{"t":"table","title":"상표 심판의 종류","head":["구분","내용"],"rows":[["상표법상 심판","보정각하결정 불복심판, 거절결정 불복심판, 상표등록무효심판, 존속기간갱신등록무효심판, 상품분류전환등록무효심판, 상표등록취소심판 등이 있다"],["조문","상표등록무효심판은 제117조, 존속기간갱신등록무효심판은 제118조, 상표등록취소심판은 제119조에 규정되어 있다"],["상품분류전환등록무효심판","상품 분류 전환에 따른 등록이 무효라고 주장할 때 청구하는 심판이다"],["그 밖의 심판","상표법에는 전용사용권 또는 통상사용권 등록취소심판과 권리범위확인심판도 규정되어 있다"],["없는 심판","상표법에는 존속기간연장등록 관련 심판, 정정심판, 정정무효심판, 통상실시권 허락의 심판이 없다"]]},{"t":"def","term":"상표법에만 있는 심판","text":"존속기간갱신등록무효심판, 상품분류전환등록무효심판, 등록취소심판은 특허법에는 없고 상표법에만 있는 심판이다","ex":["상표법상 보정이 요지변경이라는 이유로 보정각하 결정을 받은 사람은 결정 등본을 받은 날부터 3개월 이내에 불복심판을 청구할 수 있다"]}],"63":[{"t":"table","title":"상표 갱신과 전환","head":["구분","내용"],"rows":[["존속기간 갱신","상표권은 특허권과 달리 존속기간을 10년마다 갱신할 수 있으며, 갱신 등록에 무효 사유가 있으면 존속기간갱신등록무효심판을 청구할 수 있다"],["승소","존속기간갱신등록무효심판이나 상품분류전환등록무효심판에서 청구인이 승소하면 그 등록은 처음부터 없었던 것으로 간주된다"],["상품분류전환등록","이전 법에 따른 상품류 구분으로 상표권을 받은 상표권자가 해당 지정상품을 최신 상품류 구분에 맞춰 전환하여 등록받는 것이다"]]},{"t":"table","title":"상표등록 취소심판 사유","head":["사유","내용"],"rows":[["불사용","상표권자·전용사용권자·통상사용권자 중 누구도 정당한 이유 없이 등록상표를 지정상품에 취소심판청구일 전 계속하여 3년 이상 국내에서 사용하지 않았다면 취소심판 사유가 된다"],["오인·혼동","상표권자가 고의로 지정상품에 등록상표와 유사한 상표를 사용하여 소비자에게 품질을 오인하게 하거나 타인의 업무상 상품과 혼동을 일으키게 하면 취소심판 사유가 된다"],["사용권자의 오인·혼동","전용사용권자 또는 통상사용권자가 등록상표 등을 사용하여 품질 오인이나 혼동을 일으켜도, 상표권자가 상당한 주의를 기울였다면 취소 사유에서 제외된다"],["승소","취소심판에서 청구인이 승소하면 상표권은 소멸하게 된다"]]}],"64":[{"t":"table","title":"상표 거절·무효·확인","head":["구분","내용"],"rows":[["지정상품추가등록·상품분류전환등록의 거절","거절 결정을 받은 사람은 결정 등본을 받은 날부터 3개월 이내에 불복심판을 청구할 수 있다"],["상표등록 거절","거절 결정을 받은 사람은 결정 등본을 받은 날부터 3개월 이내에 심판을 청구할 수 있고, 승소하면 기존 거절 결정이 취소되고 심사가 다시 진행된다"],["상표등록 무효심판","상표등록에 무효 사유가 있으면 하자 있는 등록을 소급하여 소멸시키기 위해 무효심판을 청구하며, 후발적 무효 사유는 제외된다"],["상표 권리범위확인심판","확인대상상표가 등록상표의 보호범위에 속하는지를 확인하는 심판으로, 상표법 제121조에 규정되어 있다 · 소극적 권리범위확인심판에서 청구인이 승소하면 제3자의 상표는 상표권의 권리범위에 속하지 않는 것으로 판단되어 자유롭게 사용할 수 있게 된다"],["디자인보호법과의 차이","디자인보호법에는 취소결정 불복심판이 있고, 상표법에는 상표등록취소심판이 별도로 존재한다는 점이 주요 차이점이다"]]}],"65":[{"t":"table","title":"저작권 민사적 구제","head":["구제","내용"],"rows":[["규정","저작권법은 민사적 구제 수단으로 침해금지청구와 손해배상청구를 규정하고, 부수 제도로 정보 제공 명령과 비밀유지 명령을 둔다"],["침해정지","저작권자 등은 권리를 침해하는 사람에게 침해 행위의 정지를 청구할 수 있고, 침해할 우려가 있는 사람에게는 예방이나 손해배상 담보를 청구할 수 있다 · 침해정지를 청구하면서 침해 행위로 만들어진 물건의 폐기나 그 밖에 필요한 조치를 함께 청구할 수 있다"],["가처분","저작권자는 보전의 필요성을 입증하여 가처분 신청을 함으로써 긴급한 상황에서 침해를 신속히 막을 수 있다"],["인격권 침해","저작자 또는 실연자는 고의 또는 과실로 저작인격권이나 실연자의 인격권을 침해한 사람에게 손해배상에 갈음하거나 손해배상과 함께 명예회복에 필요한 조치를 요구할 수 있다"],["저작자 사망 후","저작자가 사망한 후에는 유족이나 유언집행자가 저작물을 침해하거나 침해할 우려가 있는 사람에게 침해 금지를 청구할 수 있다 · 고의 또는 과실로 저작인격권을 침해한 사람에게 명예회복 등을 청구할 수 있다"]]},{"t":"vs","title":"저작권 침해 대응 방법","cols":[{"name":"민사적 구제","items":["침해정지청구, 손해배상청구, 명예회복 등 청구, 정보제공명령, 비밀유지명령"]},{"name":"형사적 구제","items":["고소·고발"]}]}],"66":[{"t":"table","title":"저작권 손해배상","head":["구분","내용"],"rows":[["손해배상 청구","고의 또는 과실로 저작권을 침해하여 손해가 발생하고 침해와 손해 사이에 인과관계가 있으면 민법상 불법행위로서 손해배상을 청구할 수 있다"],["특별 규정","저작권은 무형의 재산으로 침해 사실을 알기 어렵고 권리범위가 불명확하여 손해액 산정이 어렵기 때문에 저작권법은 손해액 입증에 관한 특별 규정을 둔다"],["과실 추정","등록된 저작권 등 권리를 침해한 사람은 그 침해 행위에 과실이 있는 것으로 추정된다 · 과실이 추정되면 저작권자는 침해 사실만 입증하면 되고, 침해자가 자신에게 과실이 없음을 증명해야 책임을 피할 수 있다"]]},{"t":"table","title":"손해액 추정","head":["구분","내용"],"rows":[["침해자의 이익","저작권을 침해한 사람이 침해 행위로 얻은 이익의 액수는 저작재산권자 등이 받은 손해의 액수로 추정된다"],["통상 받을 수 있는 금액","저작권자는 권리를 행사하여 일반적으로 받을 수 있는 금액을 손해액으로 하여 배상을 청구할 수 있다 · 실제 손해액이 권리 행사로 일반적으로 받을 수 있는 금액을 초과하는 경우 그 초과액에 대해서도 손해배상을 청구할 수 있다"],["상당한 손해액","손해 발생은 인정되나 손해액을 산정하기 어려울 때 법원은 변론의 취지와 증거조사 결과를 고려하여 상당한 손해액을 인정할 수 있다"],["법정손해배상","실제 손해액 입증 없이 침해된 저작물마다 1천만 원 이하, 영리 목적의 고의 침해는 5천만 원 이하의 범위에서 청구할 수 있다 · 저작권자가 실제 손해액을 정확히 입증하기 어려울 때에도 법에서 정한 금액으로 배상을 받을 수 있게 돕는다"]]}],"67":[{"t":"vs","title":"정보제공명령과 비밀유지명령","cols":[{"name":"정보제공명령","items":["법원은 당사자의 신청에 따라 침해 행위와 관련하여 다른 당사자가 보유한 정보를 제공하라고 명령할 수 있다","저작권 침해 사건에서 저작권자가 침해 입증에 필요한 정보를 얻기 어려운 증거 수집의 어려움을 해결하기 위한 제도이다"]},{"name":"비밀유지명령","items":["당사자의 신청에 따라 영업비밀을 소송 수행 외의 목적으로 사용하거나 명령을 받은 사람 외의 사람에게 공개하지 말라고 법원이 명하는 것이다","저작권 침해 소송 과정에서 당사자의 영업비밀이 부당하게 사용되거나 유출되는 것을 막기 위한 조치이다"]}]}],"68":[{"t":"table","title":"저작권 형사적 제재","head":["구분","내용"],"rows":[["형사적 제재","저작권법은 저작권 침해죄, 부정발행죄, 출처명시위반죄 등 의무 위반에 대해 형사적 제재를 가하며, 고의로 저지른 범죄만을 처벌 대상으로 한다"],["부정발행죄·출처명시위반죄","부정발행죄는 저작물을 허락 없이 발행하는 행위를 처벌하고, 출처명시위반죄는 저작물의 출처를 명시하지 않은 경우에 적용된다"],["친고죄 원칙","저작권법은 기본적으로 권리자의 고소를 통해서만 침해자에게 형사적 제재를 할 수 있는 친고죄 원칙을 취한다"],["예외","영리를 목적으로 하거나 상습적으로 저작권을 침해하는 경우 등에는 고소가 없어도 공소를 제기할 수 있는 예외 규정이 있다"]]}]};
